    rerollIsOneRandomCall: w34callsReroll === 1, // the guard's lazy roll, nothing else
    chanceFinite: Number.isFinite(w34bP1) && Number.isFinite(w34bP2), // never NaN
    chanceClamped: w34bP1 >= 0.005 && w34bP1 <= 0.20,
