  ctxG.scene.traverse((o) => { if (o.name?.endsWith('-overlay')) overlays.push(o); });
  if (overlays.length !== 0) w38noOverlayIndependent = false;
  const gates = w38namedIn(ctxG.scene, 'lamplighter-gate');
