dispatchKey('Escape', 'wave41 close bar'); // stationOverlay() now null
// ---- Wave 42: NPC asset-contract + Unknowables gate FX ----
// a. 144 builds (12 factions × 6 classes × 2 roles) — every primed GLB
//    template must return a root with a valid proxy, a separate glow Group,
//    and a shipVisual LOD. Assets were primed at boot (line 287-290).
// b. Canonical fallback: unknown faction → independent; invalid class → light.
// c. Q-ship cover-to-real proxy swap: different classes yield different proxy
//    dimensions so the swap is always meaningful.
// d. Gate FX: gate.js still generates Unknowables lenses + plasma
//    for Unknowables-faction systems (4 lens arcs + plasma group, hidden idle,
//    visible on transit). These check gate.js behaviour, not ship geometry.
// e. Gate negatives: independent GLB ship has no unknowables-named objects;
//    veridian gate has no Unknowables FX.

// -- a. 144 builds: proxy + glow + shipVisual --
{
  let w42allBuilds = true;
  let w42allProxy = true;
  let w42allGlow = true;
  let w42allGlowGroup = true;
  let w42glowSeparate = true;
  let w42allVisual = true;
  let w42firstFail = null;
  for (const faction of NPC_FACTIONS) {
    for (const classKey of NPC_CLASSES) {
      for (const role of ['trader', 'pirate']) {
        let root;
        try { root = buildShipAsset(classKey, faction, role); }
        catch (e) {
          w42allBuilds = false;
          w42firstFail = w42firstFail ?? `${faction}:${classKey}:${role}: ${e.message}`;
          continue;
        }
        const { proxy, glow, shipVisual } = root.userData;
        if (!proxy || !Number.isFinite(proxy.rx) || proxy.rx <= 0
            || !Number.isFinite(proxy.ry) || proxy.ry <= 0
            || !Number.isFinite(proxy.halfLen) || proxy.halfLen <= 0) {
          w42allProxy = false;
          w42firstFail = w42firstFail ?? `${faction}:${classKey}:${role}: proxy invalid`;
        }
        if (!glow) { w42allGlow = false; w42firstFail = w42firstFail ?? `${faction}:${classKey}:${role}: glow missing`; }
        else if (!glow.isGroup) w42allGlowGroup = false;
        if (glow && shipVisual && glow === shipVisual) w42glowSeparate = false;
        if (!shipVisual) w42allVisual = false;
      }
    }
  }
  if (w42firstFail) console.log('wave42a first failure:', w42firstFail);
  const w42contractChecks = {
    all144Build: w42allBuilds, allHaveProxy: w42allProxy,
    allGlowPresent: w42allGlow, allGlowIsGroup: w42allGlowGroup,
    glowSeparateFromLod: w42glowSeparate, allHaveShipVisual: w42allVisual,
  };
  console.log('wave42a asset contract (144 builds):', JSON.stringify(w42contractChecks));
  if (!Object.values(w42contractChecks).every(Boolean)) { console.log('WAVE42A ASSET CONTRACT FAIL'); errors++; }
}

// -- b. canonical fallback --
{
  await primeShipAsset('__unknown__', 'light', 'trader');   // resolves to independent:light
  await primeShipAsset('independent', '__invalid__', 'trader'); // resolves to independent:light
  let w42fbOk = true;
  let w42fbMsg = null;
  try {
    const r1 = buildShipAsset('light', '__unknown__', 'trader');
    if (!r1?.userData.proxy) { w42fbOk = false; w42fbMsg = 'unknown faction: no proxy'; }
  } catch (e) { w42fbOk = false; w42fbMsg = `unknown faction: ${e.message}`; }
  try {
    const r2 = buildShipAsset('__invalid__', 'independent', 'trader');
    if (!r2?.userData.proxy) { w42fbOk = false; w42fbMsg = w42fbMsg ?? 'invalid class: no proxy'; }
  } catch (e) { w42fbOk = false; w42fbMsg = w42fbMsg ?? `invalid class: ${e.message}`; }
  if (w42fbMsg) console.log('wave42b fallback failure:', w42fbMsg);
  const w42fallbackChecks = { canonicalFallbackBuilds: w42fbOk };
  console.log('wave42b canonical fallback:', JSON.stringify(w42fallbackChecks));
  if (!Object.values(w42fallbackChecks).every(Boolean)) { console.log('WAVE42B FALLBACK FAIL'); errors++; }
}

// -- c. Q-ship cover-to-real proxy swap --
{
  const w42covRoot  = buildShipAsset('freighter', 'freehold', 'trader');
  const w42realRoot = buildShipAsset('cutter', 'redledger', 'pirate');
  const w42cp = w42covRoot.userData.proxy;
  const w42rp = w42realRoot.userData.proxy;
  const w42qshipChecks = {
    coverHasProxy: !!(w42cp && w42cp.halfLen > 0),
    realHasProxy:  !!(w42rp && w42rp.halfLen > 0),
    proxiesDiffer: !!(w42cp && w42rp && (
      w42cp.rx !== w42rp.rx || w42cp.ry !== w42rp.ry || w42cp.halfLen !== w42rp.halfLen)),
  };
  console.log('wave42c Q-ship proxy swap:', JSON.stringify(w42qshipChecks));
  if (!Object.values(w42qshipChecks).every(Boolean)) { console.log('WAVE42C QSHIP PROXY SWAP FAIL'); errors++; }
}

// -- d. gate FX: Unknowables energy-field lens arcs + plasma cells ----
const w42scopedCtx = (systemId, faction) => {
  const sceneS = new THREE.Scene();
  const cameraS = new THREE.PerspectiveCamera(70, 1280 / 720, 0.1, 20000);
  const rendererS = { domElement: makeEl('canvas'), setSize() {}, setPixelRatio() {}, setAnimationLoop() {}, render() {} };
  const ctxS = createCtx({ scene: sceneS, camera: cameraS, renderer: rendererS });
  ctxS.systems = SYSTEMS;
  ctxS.world.currentSystem = systemId;
  ctxS.world.currentFaction = faction;
  return ctxS;
};

const w42origFaction = SYSTEMS['fh_hearth'].faction;
SYSTEMS['fh_hearth'].faction = 'unknowables';
const ctx42G = w42scopedCtx('fh_hearth', 'unknowables');
const gate42 = initGate(ctx42G);
const w42gates = w38namedIn(ctx42G.scene, 'lamplighter-gate');
const w42gate = w42gates[0];
let w42fourLenses = 0;
let w42plasmaGroup = null;
if (w42gate) {
  w42gate.traverse((c) => {
    if (c.isMesh && c.name === 'unknowables-lens') w42fourLenses++;
    if (c.isGroup && c.name === 'unknowables-plasma') w42plasmaGroup = c;
  });
}
let w42overlayExists = w42fourLenses === 4 && !!w42plasmaGroup;
let w42plasmaCells = 0;
if (w42plasmaGroup) {
  for (const c of w42plasmaGroup.children) {
    if (c.isMesh && c.name === 'unknowables-plasma-cell') w42plasmaCells++;
  }
}
let w42plasmaHiddenIdle = !w42plasmaGroup || w42plasmaGroup.visible === false;
ctx42G.gate.jumping = true;
ctx42G.gate.destination = SYSTEMS['fh_hearth'].gates[0].to;
gate42.update(1 / 60);
const w42plasmaVisibleTransit = !!w42plasmaGroup && w42plasmaGroup.visible === true;
const w42origRM42d = ctx42G.settings.reducedMotion;
ctx42G.settings.reducedMotion = true;
gate42.update(1 / 60);
const w42plasmaVisibleFrozen = !!w42plasmaGroup && w42plasmaGroup.visible === true;
ctx42G.settings.reducedMotion = w42origRM42d;
ctx42G.gate.jumping = false;
ctx42G.gate.destination = null;
gate42.update(1 / 60);
const w42plasmaHiddenAgain = !w42plasmaGroup || w42plasmaGroup.visible === false;
const w42gateChecks = {
  overlayExists: w42overlayExists,
  fourLenses: w42fourLenses === 4,
  plasmaGroupExists: !!w42plasmaGroup,
  eightPlasmaCells: w42plasmaCells === 8,
  plasmaHiddenIdle: w42plasmaHiddenIdle,
  plasmaVisibleTransit: w42plasmaVisibleTransit,
  plasmaVisibleUnderReducedMotion: w42plasmaVisibleFrozen,
  plasmaHiddenAfterTransit: w42plasmaHiddenAgain,
};
console.log('wave42d gate overlay:', JSON.stringify(w42gateChecks));
if (!Object.values(w42gateChecks).every(Boolean)) { console.log('WAVE42D GATE OVERLAY FAIL'); errors++; }
SYSTEMS['fh_hearth'].faction = w42origFaction;

// -- e. gate negatives: independent ship no unknowables parts; veridian no overlay --
const w42indyCtx = w42scopedCtx('test-system', 'independent');
const w42indy = spawnLiveShip(w42indyCtx, {
  id: 'wave42-indy', name: 'Indy', classKey: 'light', faction: 'independent', role: 'trader', resolve: 50,
}, new THREE.Vector3(0, 0, -4000));
let w42indyHasUnkParts = false;
w42indy.object.traverse((c) => { if (c.name?.startsWith('unknowables-')) w42indyHasUnkParts = true; });
const ctx42V = w42scopedCtx('vd_survey', 'veridian');
const gate42V = initGate(ctx42V);
const w42veridGates = w38namedIn(ctx42V.scene, 'lamplighter-gate');
const w42veridGate = w42veridGates[0];
const w42veridHasOwnOverlay = w42veridGate && w38sculpted(w42veridGate) && w42veridGate.name === 'veridian-gate';
const w42hasUnknowablesOverlay = w42veridGate.children.some((c) => c.name?.startsWith('unknowables-'));
const w42negativeChecks = {
  independentNoUnknowablesParts: !w42indyHasUnkParts,
  veridianNoUnknowablesOverlay: !w42hasUnknowablesOverlay,
  veridianKeepsOwnOverlay: w42veridHasOwnOverlay,
};
console.log('wave42e gate negatives:', JSON.stringify(w42negativeChecks));
if (!Object.values(w42negativeChecks).every(Boolean)) { console.log('WAVE42E GATE NEGATIVES FAIL'); errors++; }
removeLiveShip(w42indyCtx, w42indy);

// ---- Wave 45: merged-detail stations, every kit faction ----
// The wave-43/44 freehold contract, generalised to all eight: each station is
// ONE merged vertex-coloured sculpt (~2,300 primitive parts in six chunks)
// whose hull colours ride the faction's weathering ladder and whose glow tints
// stay near-neutral. These pins check determinism, colour fidelity, packing,
// and teardown hygiene. The ladder arithmetic is recomputed here from
// FACTION_STYLE rather than imported from station-detail.js — an independent
// recomputation is the point of the pin.
{
  // Instrument dispose (wave-39 pattern)
  const w45disposed = new Set();
  let w45sharedDisposed = 0;
  for (const w45proto of [THREE.BufferGeometry.prototype, THREE.Material.prototype, THREE.Texture.prototype]) {
    const w45origDispose = w45proto.dispose;
    w45proto.dispose = function () {
      if (!w45disposed.has(this)) {
        w45disposed.add(this);
        if (this.userData?.shared === true) w45sharedDisposed++;
      }
      return w45origDispose.call(this);
    };
  }
  const w45resOf = (root, into = new Set()) => {
    root.traverse((o) => {
      if (o.geometry) into.add(o.geometry);
      const mats = Array.isArray(o.material) ? o.material : (o.material ? [o.material] : []);
      for (const m of mats) {
        into.add(m);
        for (const k in m) { const v = m[k]; if (v && v.isTexture) into.add(v); }
      }
    });
    return into;
  };
  // The allowed hull set for a faction: its DEDUPLICATED FACTION_STYLE palette
  // crossed with SHADES [1.0, 0.86, 0.72, 0.6]. A fixed recomputable product
  // set, not a tolerance band. The shade MUST be taken on the sRGB 8-bit
  // channels of the palette hex, exactly as station-detail.js weather() does:
  // scaling the LINEAR channels instead gives different values and fails a
  // correct sculpt (that was the wave-44 bring-up false failure).
  const w45SHADES = [1.0, 0.86, 0.72, 0.6];
  const w45allowedHull = (f) => {
    const style = FACTION_STYLE[f];
    const allowed = new Set();
    for (const hex of new Set([style.hull, style.hullDark, style.trim, style.accent, ...style.patch])) {
      const r8 = (hex >> 16) & 255;
      const g8 = (hex >> 8) & 255;
      const b8 = hex & 255;
      for (const s of w45SHADES) {
        const wh = (Math.round(r8 * s) << 16) | (Math.round(g8 * s) << 8) | Math.round(b8 * s);
        allowed.add(`#${wh.toString(16).padStart(6, '0')}`);
      }
    }
    return allowed;
  };
  const w45hullOf = (root) => (root ? root.children.find((c) => c.isMesh
    && c.material?.isMeshStandardMaterial && c.material.vertexColors === true) ?? null : null);
  const w45attrEq = (a, b) => a.length === b.length && a.every((v, i) => v === b[i]);
  const w45checks = {};
  const w45notes = [];

  for (const [f, sysId] of Object.entries(w38STATION_REPS)) {
    // Two independent builds of the same sculpt must be byte-identical: the
    // toolkit's scatter runs off the seeded RNG only, never Math.random.
    const ctxA = w38scopedCtx(sysId);
    const ctxB = w38scopedCtx(sysId);
    const stA = initStation(ctxA);
    initStation(ctxB);
    const gA = w38stationGroupOf(ctxA);
    const gB = w38stationGroupOf(ctxB);
    const hullA = w45hullOf(gA);
    const hullB = w45hullOf(gB);
    w45checks[`${f}Determinism`] = !!hullA && !!hullB
      && w45attrEq(hullA.geometry.attributes.position.array, hullB.geometry.attributes.position.array)
      && w45attrEq(hullA.geometry.attributes.color.array, hullB.geometry.attributes.color.array);

    // paletteFromStyle: every distinct hull colour sits on the ladder. The
    // ringHull rides the same material and the same rule, so scan both.
    const ringA = gA ? (gA.children.find((c) => c.isGroup) ?? null) : null;
    const allowed = w45allowedHull(f);
    const probe = new THREE.Color();
    let paletteOk = !!hullA;
    let paletteStray = 'none';
    for (const mesh of [hullA, w45hullOf(ringA)]) {
      if (!mesh || !paletteOk) continue;
      const colorAttr = mesh.geometry.attributes.color;
      const seen = new Set();
      if (colorAttr.count === 0) { paletteOk = false; break; }
      for (let i = 0; i < colorAttr.count; i++) {
        const key = `${colorAttr.getX(i)},${colorAttr.getY(i)},${colorAttr.getZ(i)}`;
        if (seen.has(key)) continue;
        seen.add(key);
        probe.setRGB(colorAttr.getX(i), colorAttr.getY(i), colorAttr.getZ(i), THREE.LinearSRGBColorSpace);
        const hex = `#${probe.getHex(THREE.SRGBColorSpace).toString(16).padStart(6, '0')}`;
        if (!allowed.has(hex)) { paletteStray = hex; paletteOk = false; break; }
      }
    }
    w45checks[`${f}PaletteFromStyle`] = paletteOk;

    // glowNearWhite: update() pulses lightMat.color (the faction's glow hue)
    // and that MULTIPLIES these vertex colours, so a saturated tint here would
    // square the hue. Vertex colours are stored LINEAR (ColorManagement
    // converts on setHex), so convert back to sRGB before applying the >= 0.6
    // rule — comparing linear values against an sRGB threshold reads ~20% too
    // dark. Both the group's glow chunk and the ring's ringGlow carry the rule.
    const glowMeshesOf = (root) => (root ? root.children.filter((c) => c.isMesh
      && c.material?.isMeshBasicMaterial && c.material.vertexColors === true
      && c.material.color.getHex() === FACTION_STYLE[f].glow) : []);
    const glowMeshes = [...glowMeshesOf(gA), ...glowMeshesOf(ringA)];
    let glowOk = glowMeshes.length === 2;
    let glowWorst = 'none';
    let worst = 1;
    for (const glow of glowMeshes) {
      const colorAttr = glow.geometry.attributes.color;
      const seenGlow = new Set();
      for (let i = 0; i < colorAttr.count; i++) {
        const key = `${colorAttr.getX(i)},${colorAttr.getY(i)},${colorAttr.getZ(i)}`;
        if (seenGlow.has(key)) continue;
        seenGlow.add(key);
        probe.setRGB(colorAttr.getX(i), colorAttr.getY(i), colorAttr.getZ(i), THREE.LinearSRGBColorSpace);
        const hex = probe.getHex(THREE.SRGBColorSpace);
        const lo = Math.min((hex >> 16) & 255, (hex >> 8) & 255, hex & 255) / 255;
        if (lo < worst) { worst = lo; glowWorst = `#${hex.toString(16).padStart(6, '0')}`; }
        if (lo < 0.6) glowOk = false;
      }
    }
    w45checks[`${f}GlowNearWhite`] = glowOk;

    // connectedness + singleMass: the hull chunk must be ONE packed mass, not a
    // scatter of islands (the wave-43 rejection). Hash-grid over 4-unit cubes,
    // two independent readings:
    //   isolated  — cells with no 6-axis neighbour at all (loose confetti)
    //   singleMass — the share of cells in the LARGEST flood-filled component
    // The second is the stronger statement and it is new in wave 46: the
    // wave-46 hollow bring-up hung its mooring spurs at y -16..-24 with nothing
    // reaching them, a 12-cell island that the isolated-cell test waved through
    // because the spurs touch each OTHER. Calibrated on the approved sculpts:
    // freehold/veridian/redledger/gilded/congregation/independent read 100%,
    // lamplighter 99.5%, assembly 99.6%, ferrous 99.7%.
    let connectedOk45 = false;
    let connectedNote = 'n/a';
    let singleMassOk = false;
    if (hullA) {
      const cellSize = 4;
      const posAttr = hullA.geometry.attributes.position;
      const grid = new Set();
      for (let i = 0; i < posAttr.count; i++) {
        grid.add(`${Math.floor(posAttr.getX(i) / cellSize)},${Math.floor(posAttr.getY(i) / cellSize)},${Math.floor(posAttr.getZ(i) / cellSize)}`);
      }
      const neighbours = (key) => {
        const [ix, iy, iz] = key.split(',').map(Number);
        return [
          `${ix + 1},${iy},${iz}`, `${ix - 1},${iy},${iz}`,
          `${ix},${iy + 1},${iz}`, `${ix},${iy - 1},${iz}`,
          `${ix},${iy},${iz + 1}`, `${ix},${iy},${iz - 1}`,
        ];
      };
      let isolated = 0;
      for (const key of grid) {
        if (!neighbours(key).some((n) => grid.has(n))) isolated++;
      }
      // Flood fill: largest connected component must hold nearly every cell.
      const seenCells = new Set();
      let largest = 0;
      let components = 0;
      for (const start of grid) {
        if (seenCells.has(start)) continue;
        components++;
        let size = 0;
        const stack = [start];
        seenCells.add(start);
        while (stack.length > 0) {
          const cur = stack.pop();
          size++;
          for (const n of neighbours(cur)) {
            if (grid.has(n) && !seenCells.has(n)) { seenCells.add(n); stack.push(n); }
          }
        }
        if (size > largest) largest = size;
      }
      connectedNote = `${isolated}/${grid.size} largest=${largest}/${grid.size} comps=${components}`;
      connectedOk45 = grid.size > 0 && isolated <= grid.size * 0.02;
      singleMassOk = grid.size > 0 && largest >= grid.size * 0.97;
    }
    w45checks[`${f}Connectedness`] = connectedOk45;
    w45checks[`${f}SingleMass`] = singleMassOk;

    // seatedDetail: lit and glazed parts must SIT ON the hull, not float beside
    // it. A windowGrid is a FLAT field, so a tall one wrapped onto a round or
    // faceted drum grazes the surface at its centre and hangs off at its edges
    // — the wave-45 bring-up sprayed thousands of window slabs into open space
    // that way, and the sculpt still passed every colour and density pin.
    // Metric: bucket the hull chunk into 2-unit cells, then require each
    // glow/glaze vertex to find hull material in its own cell or any of the 26
    // around it. The approved freehold sculpt measures 0.54% orphan glow and
    // 0.00% orphan glaze; the ring chunks are measured against ringHull in
    // their own local space.
    const w45orphanPct = (hullMesh, detailMesh) => {
      if (!hullMesh || !detailMesh) return 100;
      const cell = 2;
      const hp = hullMesh.geometry.attributes.position;
      const occupied = new Set();
      for (let i = 0; i < hp.count; i++) {
        occupied.add(`${Math.floor(hp.getX(i) / cell)},${Math.floor(hp.getY(i) / cell)},${Math.floor(hp.getZ(i) / cell)}`);
      }
      const dp = detailMesh.geometry.attributes.position;
      if (dp.count === 0) return 100;
      let orphans = 0;
      for (let i = 0; i < dp.count; i++) {
        const ix = Math.floor(dp.getX(i) / cell);
        const iy = Math.floor(dp.getY(i) / cell);
        const iz = Math.floor(dp.getZ(i) / cell);
        let near = false;
        for (let dx = -1; dx <= 1 && !near; dx++) {
          for (let dy = -1; dy <= 1 && !near; dy++) {
            for (let dz = -1; dz <= 1 && !near; dz++) {
              if (occupied.has(`${ix + dx},${iy + dy},${iz + dz}`)) near = true;
            }
          }
        }
        if (!near) orphans++;
      }
      return (100 * orphans) / dp.count;
    };
    const w45basicOf = (root, hex) => (root ? root.children.find((c) => c.isMesh
      && c.material?.isMeshBasicMaterial && c.material.vertexColors === true
      && c.material.color.getHex() === hex) ?? null : null);
    const seated = [
      w45orphanPct(hullA, w45basicOf(gA, FACTION_STYLE[f].glow)),
      w45orphanPct(hullA, w45basicOf(gA, 0xffffff)),
      w45orphanPct(w45hullOf(ringA), w45basicOf(ringA, FACTION_STYLE[f].glow)),
      w45orphanPct(w45hullOf(ringA), w45basicOf(ringA, 0xffffff)),
    ];
    w45checks[`${f}SeatedDetail`] = seated.every((p) => p <= 1);
    const seatedNote = seated.map((p) => `${p.toFixed(2)}%`).join('/');

    // teardownDisposesAll: the REAL rebuild path — station.js consumes a
    // 'systemLoaded' out of ctx.lastEvents inside update() (the wave-38 f
    // idiom); emitting alone rebuilds nothing. Rebuild into another faction's
    // system so THIS sculpt's per-build assets are the ones under audit.
    const swapTo = f === 'veridian' ? 'fh_hearth' : 'vd_survey';
    const swapName = f === 'veridian' ? 'freehold-station' : 'veridian-station';
    let teardownOk = false;
    let teardownTally = 'n/a';
    if (gA) {
      const firstBuildRes = w45resOf(gA);
      w45disposed.clear();
      w45sharedDisposed = 0;
      ctxA.lastEvents = [{ type: 'systemLoaded', to: swapTo }];
      stA.update(1 / 60);
      const gAfter = w38stationGroupOf(ctxA);
      let leaked = 0;
      for (const r of firstBuildRes) {
        if (r.userData?.shared === true) continue;
        if (!w45disposed.has(r)) leaked++;
      }
      teardownTally = `${firstBuildRes.size - leaked}/${firstBuildRes.size}`;
      teardownOk = firstBuildRes.size > 0 && leaked === 0
        && w45sharedDisposed === 0 && gA.parent === null
        && !!gAfter && gAfter.name === swapName;
    }
    w45checks[`${f}TeardownDisposesAll`] = teardownOk;

    w45notes.push(`wave45 ${f} detail: paletteStray=${paletteStray}`
      + ` glowWorstChannel=${glowWorst} teardown=${teardownTally}->${swapName}`
      + ` connectedness=${connectedNote} orphanDetail=${seatedNote}`);
  }

  for (const line of w45notes) console.log(line);
  console.log('wave45 detail stations:', JSON.stringify(w45checks));
  if (!Object.values(w45checks).every(Boolean)) { console.log('WAVE45 DETAIL STATIONS FAIL'); errors++; }
}

// ---- Wave 46: the seeded factions, EVERY live system -----------------------
// independent (12 systems) and hollow (3) used to share one placeholder sculpt;
// wave 46 gave them detail sculpts that vary their dressing per system off
// station.js's seedForSystem (FNV-1a of the system id). A per-faction
// representative is no longer enough coverage: the wave-46 bring-up shipped an
// independent sculpt whose lamp populations scaled with the seed, and the ONE
// system that drew the low end — blackstation, a generated hub with live
// traffic — landed at 25,692 glow vertices against a 32,000 floor. Every other
// system passed. So this section sweeps EVERY live system of both factions
// through the REAL initStation path, and additionally proves the variation is
// real (distinct hull geometry per system) rather than a seed that is read and
// ignored.
{
  const w46checks = {};
  const w46notes = [];
  // The wave-45 helpers are block-scoped to their own section, so the two the
  // sweep needs are re-declared here rather than hoisted — an independent
  // recomputation is the point of a pin, and hoisting would let one edit move
  // both sections at once.
  const w46hullOf = (root) => (root ? root.children.find((c) => c.isMesh
    && c.material?.isMeshStandardMaterial && c.material.vertexColors === true) ?? null : null);
  const w46orphanPct = (hullMesh, detailMesh) => {
    if (!hullMesh || !detailMesh) return 100;
    const cell = 2;
    const hp = hullMesh.geometry.attributes.position;
    const occupied = new Set();
    for (let i = 0; i < hp.count; i++) {
      occupied.add(`${Math.floor(hp.getX(i) / cell)},${Math.floor(hp.getY(i) / cell)},${Math.floor(hp.getZ(i) / cell)}`);
    }
    const dp = detailMesh.geometry.attributes.position;
    if (dp.count === 0) return 100;
    let orphans = 0;
    for (let i = 0; i < dp.count; i++) {
      const ix = Math.floor(dp.getX(i) / cell);
      const iy = Math.floor(dp.getY(i) / cell);
      const iz = Math.floor(dp.getZ(i) / cell);
      let near = false;
      for (let dx = -1; dx <= 1 && !near; dx++) {
        for (let dy = -1; dy <= 1 && !near; dy++) {
          for (let dz = -1; dz <= 1 && !near; dz++) {
            if (occupied.has(`${ix + dx},${iy + dy},${iz + dz}`)) near = true;
          }
        }
      }
      if (!near) orphans++;
    }
    return (100 * orphans) / dp.count;
  };
  for (const faction of ['independent', 'hollow']) {
    const ids = Object.keys(SYSTEMS).filter((id) => SYSTEMS[id].faction === faction);
    const sigs = new Set();
    let allDense = true;
    let allGlow = true;
    let allEnvelope = true;
    let allSeated = true;
    let allPacked = true;
    let allSingleMass = true;
    let worstGlow = Infinity;
    let worstVerts = Infinity;
    let worstFloor = 0;
    let worstMass = 1;
    for (const sysId of ids) {
      const ctxS = w38scopedCtx(sysId);
      initStation(ctxS);
      const g = w38stationGroupOf(ctxS);
      if (!g || g.name !== `${faction}-station`) { allDense = false; continue; }
      const ring = g.children.find((c) => c.isGroup) ?? null;
      const hull = w46hullOf(g);
      const glow = g.children.find((c) => c.isMesh && c.material?.isMeshBasicMaterial
        && c.material.vertexColors === true
        && c.material.color.getHex() === FACTION_STYLE[faction].glow) ?? null;
      let verts = 0;
      g.traverse((o) => { if (o.geometry) verts += o.geometry.attributes?.position?.count ?? 0; });
      if (verts < 120000) allDense = false;
      if (!glow || glow.geometry.attributes.position.count < 32000) allGlow = false;
      worstVerts = Math.min(worstVerts, verts);
      worstGlow = Math.min(worstGlow, glow ? glow.geometry.attributes.position.count : 0);
      // Envelope, measured over mesh geometry exactly as the wave-45 census does.
      const bb = new THREE.Box3();
      const one = new THREE.Box3();
      g.updateMatrixWorld(true);
      g.traverse((o) => {
        if (!o.isMesh || !o.geometry) return;
        if (!o.geometry.boundingBox) o.geometry.computeBoundingBox();
        one.copy(o.geometry.boundingBox).applyMatrix4(o.matrixWorld);
        bb.union(one);
      });
      bb.min.sub(g.position);
      bb.max.sub(g.position);
      if (bb.isEmpty()
        || Math.max(Math.abs(bb.min.x), Math.abs(bb.max.x)) > 32
        || Math.max(Math.abs(bb.min.z), Math.abs(bb.max.z)) > 32
        || bb.min.y < -26 || bb.max.y > 33) allEnvelope = false;
      worstFloor = Math.min(worstFloor, bb.min.y);
      // Seated detail and packing, per system — a seed can only vary dressing.
      if (w46orphanPct(hull, glow) > 1) allSeated = false;
      if (w46orphanPct(w46hullOf(ring), ring?.children.find((c) => c.isMesh
        && c.material?.isMeshBasicMaterial && c.material.vertexColors === true
        && c.material.color.getHex() === FACTION_STYLE[faction].glow) ?? null) > 1) allSeated = false;
      if (hull) {
        const cell = 4;
        const p = hull.geometry.attributes.position;
        const cells = new Set();
        let sig = 0;
        for (let i = 0; i < p.count; i++) {
          cells.add(`${Math.floor(p.getX(i) / cell)},${Math.floor(p.getY(i) / cell)},${Math.floor(p.getZ(i) / cell)}`);
          if (i % 97 === 0) sig = (sig + Math.round(p.getX(i) * 31 + p.getY(i) * 17 + p.getZ(i) * 7)) | 0;
        }
        const nb = (key) => {
          const [ix, iy, iz] = key.split(',').map(Number);
          return [`${ix + 1},${iy},${iz}`, `${ix - 1},${iy},${iz}`,
            `${ix},${iy + 1},${iz}`, `${ix},${iy - 1},${iz}`,
            `${ix},${iy},${iz + 1}`, `${ix},${iy},${iz - 1}`];
        };
        let isolated = 0;
        for (const key of cells) if (!nb(key).some((n) => cells.has(n))) isolated++;
        if (isolated > cells.size * 0.02) allPacked = false;
        // Single mass, per system: a seed must not detach a spur on one map and
        // leave it attached on the next (the wave-46 hollow mooring spurs).
        const seenCells = new Set();
        let largest = 0;
        for (const start of cells) {
          if (seenCells.has(start)) continue;
          let size = 0;
          const stack = [start];
          seenCells.add(start);
          while (stack.length > 0) {
            const cur = stack.pop();
            size++;
            for (const n of nb(cur)) if (cells.has(n) && !seenCells.has(n)) { seenCells.add(n); stack.push(n); }
          }
          if (size > largest) largest = size;
        }
        if (largest < cells.size * 0.97) allSingleMass = false;
        worstMass = Math.min(worstMass, largest / cells.size);
        sigs.add(`${p.count}:${sig}`);
      }
    }
    w46checks[`${faction}EverySystemDense`] = allDense;
    w46checks[`${faction}EverySystemGlow`] = allGlow;
    w46checks[`${faction}EverySystemEnvelope`] = allEnvelope;
    w46checks[`${faction}EverySystemSeated`] = allSeated;
    w46checks[`${faction}EverySystemPacked`] = allPacked;
    w46checks[`${faction}EverySystemSingleMass`] = allSingleMass;
    // Variation is real: one distinct hull signature per system, not one shared.
    w46checks[`${faction}SeedVaries`] = ids.length > 1 && sigs.size === ids.length;
    w46notes.push(`wave46 ${faction}: systems=${ids.length} distinctHulls=${sigs.size}`
      + ` worstVerts=${worstVerts} worstGlow=${worstGlow} worstFloor=${worstFloor.toFixed(1)}`
      + ` worstSingleMass=${(100 * worstMass).toFixed(1)}%`);
  }
  for (const line of w46notes) console.log(line);
  console.log('wave46 seeded factions:', JSON.stringify(w46checks));
  if (!Object.values(w46checks).every(Boolean)) { console.log('WAVE46 SEEDED FACTIONS FAIL'); errors++; }
}

// ---- Wave 49: the ship-charter pass (GLB asset edition) -------------------------
// Measures every faction × class through the real primed LOD0 visual. Checks:
// span (charter band), proportion (length/beam/height silhouette rules), pivot
// (bounding-box centre offset), proxy coverage, and class-size ladder per
// faction. Legacy tables, migration-gate conditionals, and procedural module
// imports are retired; all 12 factions use the one charter.
{
  const {
    proportionFor, scaleFor,
    CLASS_ORDER, FACTION_REBUILD_ORDER,
  } = await import('../src/game/ship-scale.js');

  // Elliptic capsule vertex-coverage helper (mirrors combat.js testNpcHits).
  const w49proxyCover = (visual, proxy) => {
    if (!visual || !proxy || !Number.isFinite(proxy.rx) || proxy.rx <= 0
        || !Number.isFinite(proxy.ry) || proxy.ry <= 0
        || !Number.isFinite(proxy.halfLen)) return 0;
    const rx2 = proxy.rx * proxy.rx;
    const ry2 = proxy.ry * proxy.ry;
    const minR2 = Math.min(rx2, ry2);
    let total = 0;
    let inside = 0;
    visual.traverse((obj) => {
      if (!obj.isMesh) return;
      const pos = obj.geometry?.attributes?.position;
      if (!pos) return;
      for (let i = 0; i < pos.count; i++) {
        total++;
        const x = pos.getX(i);
        const y = pos.getY(i);
        const z = pos.getZ(i);
        const cz = z < -proxy.halfLen ? -proxy.halfLen : z > proxy.halfLen ? proxy.halfLen : z;
        const dz = z - cz;
        const rxy2 = x * x + y * y;
        if (rxy2 === 0) { if (dz * dz <= minR2) inside++; }
        else { const E = x * x / rx2 + y * y / ry2; if (E * (rxy2 + dz * dz) <= rxy2) inside++; }
      }
    });
    return total > 0 ? (100 * inside) / total : 100;
  };

  const w49checks = {};
  const w49notes = [];

  for (const f of FACTION_REBUILD_ORDER) {
    const sizes = {};
    let allSpan = true;
    let allProportion = true;
    let allPivot = true;
    let allProxyCover = true;
    let allClassOrdering = true;
    let worstSpan = { class: 'none', size: 0, band: '', use: 0 };
    let worstProportion = { class: 'none', metric: '' };
    let worstPivot = { class: 'none', axis: '', offset: 0, limit: 0 };
    let worstProxyCover = { class: 'none', pct: 100 };

    for (const ck of CLASS_ORDER) {
      const root = buildShipAsset(ck, f, 'trader');
      const visual = root.userData.shipVisual;
      if (!visual) { allSpan = false; allProportion = false; allPivot = false; continue; }

      const box = new THREE.Box3().setFromObject(visual);
      const spanX = box.max.x - box.min.x;
      const spanY = box.max.y - box.min.y;
      const spanZ = box.max.z - box.min.z;
      const size = Math.max(spanX, spanY, spanZ);
      sizes[ck] = size;

      // SPAN: must land inside charter [span[0], span[1]]
      const table = scaleFor(ck);
      const spanMin = table.span[0];
      const spanMax = table.span[1];
      const spanUse = size < spanMin
        ? (size - spanMin) / (spanMax - spanMin)
        : size > spanMax ? (size - spanMax) / (spanMax - spanMin) : 0;
      if (size < spanMin || size > spanMax) allSpan = false;
      if (Math.abs(spanUse) > Math.abs(worstSpan.use)) {
        worstSpan = { class: ck, size, band: `[${spanMin.toFixed(1)},${spanMax.toFixed(1)}]`, use: spanUse };
      }

      // PROPORTION: length-over-beam, height-over-length, beam-over-length
      const prop = proportionFor(ck, f);
      const lbRatio = spanX > 0 ? spanZ / spanX : 0;
      const hlRatio = spanZ > 0 ? spanY / spanZ : 0;
      const blRatio = spanZ > 0 ? spanX / spanZ : 0;
      if (lbRatio < prop.minLengthOverBeam || hlRatio > prop.maxHeightOverLength || blRatio < prop.minBeamOverLength) {
        allProportion = false;
        if (worstProportion.metric === '') {
          const fail = lbRatio < prop.minLengthOverBeam
            ? `lb${lbRatio.toFixed(2)}<${prop.minLengthOverBeam}`
            : hlRatio > prop.maxHeightOverLength
              ? `hl${hlRatio.toFixed(2)}>${prop.maxHeightOverLength}`
              : `bl${blRatio.toFixed(2)}<${prop.minBeamOverLength}`;
          worstProportion = { class: ck, metric: fail };
        }
      }

      // PIVOT: bounding-box centre within maxPivotOffset of origin on each axis
      const cx = (box.min.x + box.max.x) / 2;
      const cy = (box.min.y + box.max.y) / 2;
      const cz = (box.min.z + box.max.z) / 2;
      const ox = spanX > 0 ? Math.abs(cx) / spanX : 0;
      const oy = spanY > 0 ? Math.abs(cy) / spanY : 0;
      const oz = spanZ > 0 ? Math.abs(cz) / spanZ : 0;
      const maxOffset = prop.maxPivotOffset;
      if (ox > maxOffset || oy > maxOffset || oz > maxOffset) {
        allPivot = false;
        if (worstPivot.axis === '') {
          const axis = ox > maxOffset ? 'x' : oy > maxOffset ? 'y' : 'z';
          const off = axis === 'x' ? ox : axis === 'y' ? oy : oz;
          worstPivot = { class: ck, axis, offset: off, limit: maxOffset };
        }
      }

      // PROXY COVER: >= 80 % of LOD0 mesh vertices inside the derived capsule
      const proxy = root.userData.proxy;
      if (proxy) {
        const coverPct = w49proxyCover(visual, proxy);
        if (coverPct < 80) {
          allProxyCover = false;
          if (coverPct < worstProxyCover.pct) worstProxyCover = { class: ck, pct: coverPct };
        }
      }
    }

    // CLASS ORDERING: light ≤ ace (within 15 %) < cutter < heavy < frigate << freighter
    const s = sizes;
    const allPresent = CLASS_ORDER.every((ck) => (s[ck] ?? 0) > 0);
    if (allPresent) {
      const lightVsAce = Math.abs((s.light - s.ace) / Math.max(s.light, s.ace)) <= 0.15;
      allClassOrdering = lightVsAce
        && s.ace < s.cutter && s.cutter < s.heavy
        && s.heavy < s.frigate && s.frigate < s.freighter;
    } else {
      allClassOrdering = false;
    }

    w49checks[`${f}Span`] = allSpan;
    w49checks[`${f}Proportion`] = allProportion;
    w49checks[`${f}Pivot`] = allPivot;
    w49checks[`${f}ProxyCover`] = allProxyCover;
    w49checks[`${f}ClassOrdering`] = allClassOrdering;
    w49notes.push(`wave49 ${f}:`
      + ` span=${worstSpan.class}@${worstSpan.size.toFixed(1)}${worstSpan.band}@${(100 * worstSpan.use).toFixed(0)}%`
      + ` proportion=${worstProportion.class}:${worstProportion.metric || 'ok'}`
      + ` pivot=${worstPivot.class}:${worstPivot.axis || 'ok'}${worstPivot.offset.toFixed(2)}`
      + ` proxyCover=${worstProxyCover.class}@${worstProxyCover.pct.toFixed(1)}%`
      + ` ladder=${CLASS_ORDER.map((ck) => `${ck}=${s[ck]?.toFixed(1) ?? '?'}`).join(',')}`);
  }
  for (const line of w49notes) console.log(line);
  console.log('wave49 ship charter:', JSON.stringify(w49checks));
  if (!Object.values(w49checks).every(Boolean)) { console.log('WAVE49 SHIP CHARTER FAIL'); errors++; }
}

// ---- Wave 51: the ore ladder (nine ores, four cutting heads) --------------
// Mining is no longer the single WEAPONS.mining row. ORE_TYPES gives nine
// ores a hardness (1..4), an extraction resist, and a full visual recipe;
// ORE_BAND_WEIGHTS composes fields by system band; MINING_LASERS is the
// four-head ladder the outfitter sells strictly in order (array index ===
// ctx.world.miningLaser); combat.js's updateMining gates on
// hardness > head.tier and tells the world first ('mineBlocked', throttled
// to 1/s per rock); asteroids.js fans the field out into ONE InstancedMesh
// per ore key, extracts at extractPerSec / extractResist, and drops
// ore-tinted pods; save.js persists the rung and heals tampered ones;
// market.js's strikeRush/oreRush move the new ores while NPC manifests stay
// byte-identical (LEGAL_KEYS is legal && bulk); authored systems price the
// exotics so hauling hard ore coreward pays. Method: the LIVE boot ctx for
// the freehold field and the outfitter/save cases, scoped throwaway
// contexts (the wave-38 idiom) for determinism, teardown, and the beam
// cases — the real initAsteroids/initCombat/initPods/initStation paths
// throughout, never reimplemented arithmetic except where an independent
// recomputation IS the pin (a, b, l, m).
{
  const {
    ORE_TYPES, ORE_KEYS, ORE_BAND_WEIGHTS, pickOreType, oreKeysForBand,
    MINING_LASERS, miningLaserFor, WEAPONS, createShipState,
  } = await import('../src/game/state.js');
  const { AUTHORED_SYSTEMS } = await import('../src/game/authored-systems.js');
  const { initPrices, applyEventPressure } = await import('../src/game/market.js');
  const { MODEL_CATALOG } = await import('../src/game/model-catalog.js');
  const { initPods: initPods51 } = await import('../src/game/pods.js');

  // Scoped throwaway context (the wave-38 w38scopedCtx idiom).
  const w51scopedCtx = (systemId) => {
    const sceneS = new THREE.Scene();
    const cameraS = new THREE.PerspectiveCamera(70, 1280 / 720, 0.1, 20000);
    const rendererS = { domElement: makeEl('canvas'), setSize() {}, setPixelRatio() {}, setAnimationLoop() {}, render() {} };
    const ctxS = createCtx({ scene: sceneS, camera: cameraS, renderer: rendererS });
    ctxS.systems = SYSTEMS;
    ctxS.world.currentSystem = systemId;
    return ctxS;
  };
  // Mirrors updateMining's ray-sphere pick — used ONLY to choose a vantage
  // whose line to the chosen rock is clear; the assertions then fire
  // through the REAL beam, which must land on the same rock.
  const w51ClearLine = (list, cand, gap, range) => {
    const nose = new THREE.Vector3(cand.position.x, cand.position.y, cand.position.z + cand.radius + gap - 2.4);
    const dir = new THREE.Vector3(0, 0, -1);
    const oc = new THREE.Vector3();
    let bestT = range;
    let best = null;
    for (const a of list) {
      oc.subVectors(nose, a.position);
      const b = oc.dot(dir);
      const c = oc.lengthSq() - a.radius * a.radius;
      const disc = b * b - c;
      if (disc < 0) continue;
      const sq = Math.sqrt(disc);
      let th = -b - sq;
      if (th < 0) th = -b + sq;
      if (th < 0 || th > bestT) continue;
      bestT = th;
      best = a;
    }
    return best === cand;
  };
  // Park the scoped ship nose-on to `rock`: identity quaternion puts local
  // -Z (the nose) on the rock, dead ahead at gap + radius along +z.
  const w51AimAt = (ctxS, rock, gap) => {
    ctxS.ship.object.position.set(rock.position.x, rock.position.y, rock.position.z + rock.radius + gap);
    ctxS.ship.object.quaternion.identity();
    ctxS.ship.velocity.set(0, 0, 0);
    ctxS.targets.current = null; // a targeted asteroid ref would pull the beam
    // Combat fires the camera→reticle ray, not ship −Z. Park first-person
    // on the nose axis so screen-center hits the same rock the old nose ray did.
    ctxS.flags.camera = 'first';
    ctxS.flags.firstPerson = true;
    ctxS.targets.reticleScreen = { x: 0, y: 0 };
    ctxS.camera.position.copy(ctxS.ship.object.position);
    ctxS.camera.quaternion.identity();
    ctxS.camera.up.set(0, 1, 0);
    ctxS.camera.updateMatrixWorld();
  };
  // Scoped frame stepper — the main tick() rotation order: world time
  // advances, updates run in init order (asteroids BEFORE combat, so a
  // mineHit emitted this frame extracts next frame), the queue rotates.
  // Returns every event emitted across the n frames.
  // track { id, gap }: re-park on list[id] each frame (closed-form orbit).
  const w51step = (ctxS, updates, n, track) => {
    const out = [];
    const id = track && Number.isInteger(track.id) ? track.id : -1;
    const gap = track && Number.isFinite(track.gap) ? track.gap : 20;
    for (let i = 0; i < n; i++) {
      if (id >= 0) {
        const rock = ctxS.asteroids.list[id];
        if (rock) w51AimAt(ctxS, rock, gap);
      }
      ctxS.elapsed += dt;
      ctxS.world.time += dt;
      for (const u of updates) u.update(dt);
      out.push(...ctxS.events);
      ctxS.lastEvents = ctxS.events;
      ctxS.events = [];
    }
    return out;
  };

  // -- a. contract shape: the tables the whole wave stands on -------------
  // Every ore key is a real commodity that names itself; hardness is a
  // 1..4 integer with the 2/2/3/2 census the band ladders are priced
  // around; band weight tables reference only real ores with positive
  // weight; the four heads climb tier 1..4 with costs climbing from free;
  // miningLaserFor heals every off-ladder shape a hand-edited save can
  // carry; and WEAPONS.mining stays value-identical to the pre-wave-51 row
  // so the damage family and every older pin survive untouched.
  const w51census = {};
  for (const k of ORE_KEYS) w51census[ORE_TYPES[k].hardness] = (w51census[ORE_TYPES[k].hardness] ?? 0) + 1;
  const w51aChecks = {
    keysHaveCommodities: ORE_KEYS.every((k) => !!COMMODITIES[k]),
    commoditySelfNamed: ORE_KEYS.every((k) => ORE_TYPES[k].commodity === k),
    hardnessBounded: ORE_KEYS.every((k) => Number.isInteger(ORE_TYPES[k].hardness)
      && ORE_TYPES[k].hardness >= 1 && ORE_TYPES[k].hardness <= 4),
    nineOres: ORE_KEYS.length === 9,
    hardnessCensus: (w51census[1] ?? 0) === 2 && (w51census[2] ?? 0) === 2
      && (w51census[3] ?? 0) === 3 && (w51census[4] ?? 0) === 2,
    bandWeightsReal: Object.values(ORE_BAND_WEIGHTS).every((w) => Object.entries(w)
      .every(([k, wt]) => ORE_KEYS.includes(k) && Number.isFinite(wt) && wt > 0)),
    fourHeads: MINING_LASERS.length === 4,
    tiersAscending: MINING_LASERS.every((l, i) => l.tier === i + 1),
    costsAscending: MINING_LASERS[0].cost === 0
      && MINING_LASERS.every((l, i) => i === 0 || l.cost > MINING_LASERS[i - 1].cost),
    laserForHeals: [-1, 99, null, '2', 2.5].every((v) => miningLaserFor(v) === MINING_LASERS[0]),
    laserForLadder: [0, 1, 2, 3].every((i) => miningLaserFor(i) === MINING_LASERS[i]),
    weaponsMiningStock: WEAPONS.mining.name === 'Mining laser Mk I' && WEAPONS.mining.damage === 4
      && WEAPONS.mining.rof === 4 && WEAPONS.mining.speed === 0 && WEAPONS.mining.range === 90
      && WEAPONS.mining.heatPerShot === 2 && WEAPONS.mining.family === 'mining'
      && WEAPONS.mining.beam === true && WEAPONS.mining.extractPerSec === 1.2,
  };
  console.log('wave51a ore ladder contract:', JSON.stringify(w51aChecks));
  if (!Object.values(w51aChecks).every(Boolean)) { console.log('WAVE51A ORE LADDER CONTRACT FAIL'); errors++; }

  // -- b. pickOreType: distribution, determinism, the 5% living-rock roll --
  // A fine roll sweep per band must never leave the band's weight table.
  // Band 0's livingRock share is THE pre-wave-51 field feel: the old code
  // rolled rng() < 0.05 for living rock, and the 62/5 weight split
  // reproduces that exactly — a drift here silently changes every core
  // field in the game. Determinism per roll is what makes a system's
  // composition stable run to run (sub-case d proves it end-to-end).
  const W51_STEPS = 1000;
  let w51bKeysInTable = true;
  let w51bDeterministic = true;
  let w51lrCount = 0;
  const w51band0Seen = new Set();
  const w51band4Seen = new Set();
  for (let band = 0; band <= 4; band++) {
    const table = ORE_BAND_WEIGHTS[band];
    for (let s = 0; s < W51_STEPS; s++) {
      const roll = s / W51_STEPS;
      const key = pickOreType(band, roll);
      if (!(key in table)) w51bKeysInTable = false;
      if (pickOreType(band, roll) !== key) w51bDeterministic = false;
      if (band === 0) { w51band0Seen.add(key); if (key === 'livingRock') w51lrCount++; }
      if (band === 4) w51band4Seen.add(key);
    }
  }
  const w51lrShare = w51lrCount / W51_STEPS;
  const w51bChecks = {
    keysInBandTable: w51bKeysInTable,
    sameRollSameKey: w51bDeterministic,
    livingRockShareFivePct: w51lrShare >= 0.045 && w51lrShare <= 0.055,
    band4YieldsH4Pair: w51band4Seen.has('voidPlatinum') && w51band4Seen.has('wakeglass'),
    band0YieldsNeither: !w51band0Seen.has('voidPlatinum') && !w51band0Seen.has('wakeglass'),
  };
  console.log('wave51b pickOreType sweep:', JSON.stringify(w51bChecks), `livingRockShare=${(w51lrShare * 100).toFixed(1)}%`);
  if (!Object.values(w51bChecks).every(Boolean)) { console.log('WAVE51B PICKORETYPE FAIL'); errors++; }

  // -- c. real field fan-out at freehold (band 0), LIVE boot ctx ----------
  // The live scene after a real jump to freehold: one InstancedMesh per ore
  // key the band-0 table actually drew, instance counts summing to the
  // field def, and a flat list whose index IS the asteroidId the beam
  // events name. No mesh may exist for an ore band 0 cannot produce — an
  // empty-mesh leak would waste a draw call and break the per-ore count.
  // The pins read the meshes THIS jump's rebuild created (diffed against a
  // pre-travel snapshot): earlier waves' fresh-harness boots (wave-9/10
  // origin beats) share asteroids.js's module-level fieldMeshes with the
  // live ctx, and one of their systemLoaded rebuilds orphaned the live
  // field of that era (its meshes are still parked in the scene, disposed
  // but never removed — a harness artifact, not a game bug: the browser
  // never runs two contexts).
  if (ctx.flags.docked) undockStation(); // wave 41 left the run docked at redmarch
  const w51preMeshes = new Set();
  scene.traverse((o) => { if (o.name?.startsWith('asteroid-field-')) w51preMeshes.add(o); });
  if (ctx.world.currentSystem !== 'freehold') travelTo('freehold', 'wave51 freehold leg');
  tick(5, 'wave51 freehold field settle');
  const w51liveMeshes = [];
  scene.traverse((o) => {
    if (o.name?.startsWith('asteroid-field-') && !w51preMeshes.has(o)) w51liveMeshes.push(o);
  });
  const w51liveOreKeys = w51liveMeshes.map((m) => m.userData.oreKey);
  const w51band0Keys = oreKeysForBand(0);
  const w51listC = ctx.asteroids.list;
  const w51cChecks = {
    atFreehold: ctx.world.currentSystem === 'freehold',
    atLeastTwoMeshes: w51liveMeshes.length >= 2,
    oreKeysReal: w51liveOreKeys.every((k) => !!ORE_TYPES[k]),
    oreKeysInBand: w51liveOreKeys.every((k) => w51band0Keys.includes(k)),
    noOutOfBandMesh: ['gildvein', 'emberglass', 'voidPlatinum', 'wakeglass']
      .every((k) => !w51liveOreKeys.includes(k)),
    instanceSumIsCount: w51liveMeshes.reduce((n, m) => n + m.count, 0) === SYSTEMS.freehold.field.count,
    listLengthIsCount: w51listC.length === SYSTEMS.freehold.field.count,
    entriesWellFormed: w51listC.every((e, i) => e.id === i
      && typeof e.commodity === 'string' && !!ORE_TYPES[e.commodity]
      && typeof e.oreKey === 'string' && !!ORE_TYPES[e.oreKey]
      && Number.isInteger(e.hardness) && e.hardness === ORE_TYPES[e.oreKey].hardness
      && e.ore >= 1),
  };
  console.log('wave51c freehold field fan-out:', JSON.stringify(w51cChecks),
    `meshes=${w51liveMeshes.map((m) => `${m.userData.oreKey}:${m.count}`).join(',')}`);
  if (!Object.values(w51cChecks).every(Boolean)) { console.log('WAVE51C FIELD FAN-OUT FAIL'); errors++; }

  // -- d. determinism: two scoped builds, identical ore-key sequence ------
  // The field RNG is seeded off worldSeed and the ore draw runs FIRST, so
  // the same system must compose identically every boot — a save restored
  // beside a rock must find the same rock.
  const ctxD1 = w51scopedCtx('freehold');
  initAsteroids(ctxD1);
  const ctxD2 = w51scopedCtx('freehold');
  initAsteroids(ctxD2);
  const w51seq1 = ctxD1.asteroids.list.map((e) => e.oreKey).join(',');
  const w51seq2 = ctxD2.asteroids.list.map((e) => e.oreKey).join(',');
  const w51dChecks = { compositionStableRunToRun: w51seq1 === w51seq2 };
  console.log('wave51d field determinism:', JSON.stringify(w51dChecks), `rocks=${ctxD1.asteroids.list.length}`);
  if (!Object.values(w51dChecks).every(Boolean)) { console.log('WAVE51D FIELD DETERMINISM FAIL'); errors++; }

  // -- e. deep-rim composition really differs (verge, band 4) -------------
  // Scoped, not flown: the live run's flight state stays parked at
  // freehold. Band 0's table contains NO hardness-4 ore at all (share must
  // be exactly 0); band 4 is where void platinum and wakeglass live, so
  // the Verge must field at least one and its share must clear zero.
  const ctxV = w51scopedCtx('verge');
  initAsteroids(ctxV);
  const w51freeH4Share = ctxD1.asteroids.list.filter((e) => e.hardness === 4).length / ctxD1.asteroids.list.length;
  const w51vergeH4 = ctxV.asteroids.list.filter((e) => e.hardness === 4).length;
  const w51vergeH4Share = w51vergeH4 / ctxV.asteroids.list.length;
  const w51eChecks = {
    vergeFieldsH4: w51vergeH4 >= 1,
    freeholdH4ShareZero: w51freeH4Share === 0,
    vergeShareStrictlyGreater: w51vergeH4Share > w51freeH4Share,
  };
  console.log('wave51e deep-rim composition:', JSON.stringify(w51eChecks),
    `vergeH4=${w51vergeH4}/${ctxV.asteroids.list.length} freeholdH4share=${w51freeH4Share}`);
  if (!Object.values(w51eChecks).every(Boolean)) { console.log('WAVE51E DEEP-RIM COMPOSITION FAIL'); errors++; }

  // -- f. jump teardown disposes EVERY per-ore mesh -----------------------
  // rebuild()'s contract: a leaked field mesh across a jump is a hard
  // failure. dispose is patched on every captured geometry/material (the
  // wave-45 instrumentation, instance-scoped), then a real systemLoaded
  // rides the module's own consume (the wave-38f idiom): old meshes leave
  // the scene, every resource disposes, and ctx.asteroids.list is a NEW
  // array (never mutated — combat drops stale entries immediately).
  const ctxF = w51scopedCtx('freehold');
  const astF = initAsteroids(ctxF);
  const w51captured = [];
  ctxF.scene.traverse((o) => {
    if (o.name?.startsWith('asteroid-field-')) w51captured.push({ mesh: o, geo: o.geometry, mat: o.material });
  });
  const w51disposed = new Set();
  for (const cap of w51captured) {
    for (const res of [cap.geo, cap.mat]) {
      const orig = res.dispose.bind(res);
      res.dispose = () => { w51disposed.add(res); orig(); };
    }
  }
  const w51listBefore = ctxF.asteroids.list;
  ctxF.lastEvents = [{ type: 'systemLoaded', to: 'veridian' }];
  astF.update(dt); // the real consume: rebuild() then one frame of mesh life
  const w51fChecks = {
    meshesCaptured: w51captured.length >= 2,
    oldMeshesLeaveScene: w51captured.every((cap) => cap.mesh.parent === null),
    everyResourceDisposed: w51captured.every((cap) => w51disposed.has(cap.geo) && w51disposed.has(cap.mat)),
    listIsNewArray: ctxF.asteroids.list !== w51listBefore
      && ctxF.asteroids.list.length === SYSTEMS.veridian.field.count,
  };
  console.log('wave51f jump teardown:', JSON.stringify(w51fChecks),
    `disposed=${w51disposed.size}/${w51captured.length * 2}`);
  if (!Object.values(w51fChecks).every(Boolean)) { console.log('WAVE51F JUMP TEARDOWN FAIL'); errors++; }

  // -- g. the hardness gate through the REAL beam -------------------------
  // Scoped freehold field, real initAsteroids + initCombat, the ship
  // parked nose-on to a REAL h>1 rock found by searching the built list
  // (never a fabricated asteroid — the raycast is the point). A real
  // systemLoaded frame first: the module's own consume rebuilds the field
  // AND resets the mineBlocked throttle, so the first refusal fires
  // immediately. Then weapon group 3 with fireHeld, exactly as a player.
  const ctxG = w51scopedCtx('freehold');
  const astG = initAsteroids(ctxG);
  const combatG = initCombat(ctxG);
  initPods51(ctxG); // the real ctx.pods channel — the mk4 half drops pods
  ctxG.player = createShipState('light');
  ctxG.ship.object = new THREE.Object3D();
  ctxG.scene.add(ctxG.ship.object);
  ctxG.world.miningLaser = 0; // the stock Mk I, tier 1
  ctxG.lastEvents = [{ type: 'systemLoaded', to: 'freehold' }];
  w51step(ctxG, [astG, combatG], 1); // fresh-field consume (throttle reset)
  const w51hardRock = ctxG.asteroids.list.find((e) => e.hardness > 1
    && w51ClearLine(ctxG.asteroids.list, e, 20, MINING_LASERS[0].range)) ?? null;
  let w51g1Checks = { aimedAtRealHardRock: false };
  let w51g2Checks = { mk4Cuts: false };
  if (w51hardRock) {
    w51AimAt(ctxG, w51hardRock, 20);
    ctxG.input.weaponGroup = 3;
    ctxG.input.fireHeld = true;
    const w51oreBefore = ctxG.asteroids.list[w51hardRock.id].ore;
    const w51blockedEvs = w51step(ctxG, [astG, combatG], 72, { id: w51hardRock.id, gap: 20 }); // 1.2 s of held fire
    ctxG.input.fireHeld = false;
    const w51blockedFor = w51blockedEvs.filter((e) => e.type === 'mineBlocked' && e.asteroidId === w51hardRock.id);
    const w51firstBlocked = w51blockedFor[0] ?? null;
    const w51expectedNeeds = MINING_LASERS.find((l) => l.tier >= w51hardRock.hardness);
    w51g1Checks = {
      aimedAtRealHardRock: w51hardRock.hardness > MINING_LASERS[0].tier,
      blockedFired: w51blockedFor.length >= 1,
      blockedNamesRock: !!w51firstBlocked && w51firstBlocked.oreKey === w51hardRock.oreKey
        && w51firstBlocked.hardness === w51hardRock.hardness,
      blockedNeedsLowestHead: !!w51firstBlocked && w51firstBlocked.needs === w51expectedNeeds
        && w51firstBlocked.needs.tier >= w51hardRock.hardness,
      blockedLineVerbatim: !!w51firstBlocked
        && w51firstBlocked.line === ORE_TYPES[w51hardRock.oreKey].blockedLine
        && typeof w51firstBlocked.line === 'string' && w51firstBlocked.line.length > 0,
      noMineHitWhileBlocked: w51blockedEvs.filter((e) => e.type === 'mineHit').length === 0,
      oreUntouched: ctxG.asteroids.list[w51hardRock.id].ore === w51oreBefore,
      throttledToOnePerSec: w51blockedFor.length >= 1 && w51blockedFor.length <= 2, // 72 frames, NOT 72 events
    };
    // Second half: the Deepcore lance (tier 4) opens the same rock.
    ctxG.world.miningLaser = 3;
    ctxG.input.fireHeld = true;
    const w51hitEvs = w51step(ctxG, [astG, combatG], 90, { id: w51hardRock.id, gap: 20 }); // 1.5 s of held fire
    ctxG.input.fireHeld = false;
    const w51hits = w51hitEvs.filter((e) => e.type === 'mineHit' && e.asteroidId === w51hardRock.id);
    w51g2Checks = {
      mk4Cuts: w51hits.length > 0,
      hitNamesInstalledHead: !!w51hits[0] && w51hits[0].laserTier === 4
        && w51hits[0].extractPerSec === MINING_LASERS[3].extractPerSec,
      oreDrops: ctxG.asteroids.list[w51hardRock.id].ore < w51oreBefore,
      noBlockedNow: w51hitEvs.filter((e) => e.type === 'mineBlocked' && e.asteroidId === w51hardRock.id).length === 0,
    };
  }
  console.log('wave51g1 hardness gate blocked half:', JSON.stringify(w51g1Checks),
    w51hardRock ? `rock=${w51hardRock.id}:${w51hardRock.oreKey}:h${w51hardRock.hardness}` : 'no clear hard rock');
  if (!Object.values(w51g1Checks).every(Boolean)) { console.log('WAVE51G1 HARDNESS GATE FAIL'); errors++; }
  console.log('wave51g2 hardness gate mk4 half:', JSON.stringify(w51g2Checks));
  if (!Object.values(w51g2Checks).every(Boolean)) { console.log('WAVE51G2 MK4 CUT FAIL'); errors++; }

  // -- h. mining visual objects exist and hide correctly ------------------
  // The five FX objects live in the scene from initCombat, hidden until a
  // beam exists; firing at a reachable rock shows beam + core; the dock
  // owns the screen and freezes weapons cold (the combat.js early return).
  const ctxH = w51scopedCtx('freehold');
  const astH = initAsteroids(ctxH);
  const combatH = initCombat(ctxH);
  initPods51(ctxH); // the real ctx.pods channel — the firing leg can drop a pod
  const w51fx = {};
  for (const n of ['mine-beam', 'mine-beam-core', 'mine-glow', 'mine-sparks', 'mine-dust']) {
    w51fx[n] = ctxH.scene.getObjectByName(n) ?? null;
  }
  ctxH.player = createShipState('light');
  ctxH.ship.object = new THREE.Object3D();
  ctxH.scene.add(ctxH.ship.object);
  ctxH.world.miningLaser = 0;
  const w51softTarget = ctxH.asteroids.list.find((e) => e.oreKey === 'rawOre'
    && w51ClearLine(ctxH.asteroids.list, e, 20, MINING_LASERS[0].range)) ?? null;
  const w51hChecks = {
    allFiveExist: Object.values(w51fx).every((o) => !!o),
    allHiddenWhileCold: Object.values(w51fx).every((o) => o && o.visible === false),
    aimedAtSoftRock: !!w51softTarget,
    glowHasRadialMap: !!(w51fx['mine-glow']?.material?.map),
    ribbonHasFadeMap: !!(w51fx['mine-beam']?.material?.map),
  };
  if (w51softTarget) {
    w51AimAt(ctxH, w51softTarget, 20);
    ctxH.input.weaponGroup = 3;
    ctxH.input.fireHeld = true;
    w51step(ctxH, [astH, combatH], 2, { id: w51softTarget.id, gap: 20 });
    w51hChecks.beamShownWhileFiring = w51fx['mine-beam'].visible === true
      && w51fx['mine-beam-core'].visible === true && w51fx['mine-glow'].visible === true;
    const w51quad = w51fx['mine-beam'].geometry.attributes.position.array;
    const w51muzzle = Math.hypot(w51quad[0] - w51quad[3], w51quad[1] - w51quad[4], w51quad[2] - w51quad[5]);
    const w51contact = Math.hypot(w51quad[6] - w51quad[9], w51quad[7] - w51quad[10], w51quad[8] - w51quad[11]);
    w51hChecks.lanceThin = w51muzzle > 0.05 && w51muzzle < 0.28 && w51contact > w51muzzle && w51contact < 0.40;
    w51hChecks.glowTight = w51fx['mine-glow'].scale.x > 0.3 && w51fx['mine-glow'].scale.x < 1.5;
    ctxH.input.fireHeld = false;
    w51step(ctxH, [astH, combatH], 1);
    ctxH.flags.docked = true;
    ctxH.input.fireHeld = true; // a held trigger at the dock must stay cold
    w51step(ctxH, [astH, combatH], 1);
    w51hChecks.dockHidesBeamCoreGlow = w51fx['mine-beam'].visible === false
      && w51fx['mine-beam-core'].visible === false && w51fx['mine-glow'].visible === false;
  }
  console.log('wave51h mining fx visibility:', JSON.stringify(w51hChecks));
  if (!Object.values(w51hChecks).every(Boolean)) { console.log('WAVE51H MINING FX FAIL'); errors++; }

  // -- i. extraction resist and pod tint through the real beam ------------
  // Same head (Mk IV, 4.4 u/s raw), same frames, two rocks: soft rawOre
  // (resist 1.0) vs chromeSalt (resist 1.9). The resist divisor is real,
  // not decorative — the hard rock must yield STRICTLY fewer units, and
  // the pods carry the rock's commodity AND its podTint. Pods are counted
  // from ctx.pods (pods.js's update is not stepped: no scooping mid-pin).
  const ctxI = w51scopedCtx('freehold');
  const astI = initAsteroids(ctxI);
  const combatI = initCombat(ctxI);
  initPods51(ctxI); // the real ctx.pods channel
  ctxI.player = createShipState('light');
  ctxI.ship.object = new THREE.Object3D();
  ctxI.scene.add(ctxI.ship.object);
  ctxI.world.miningLaser = 3; // Mk IV on both runs — the head is not the variable
  ctxI.input.weaponGroup = 3;
  const W51_FIRE_FRAMES = 120; // 2 s of held fire per rock
  const w51podUnits = () => ctxI.pods.reduce((n, p) => n + p.contents.reduce((m, c) => m + c.units, 0), 0);
  const w51softRock = ctxI.asteroids.list.find((e) => e.oreKey === 'rawOre' && e.ore >= 8
    && w51ClearLine(ctxI.asteroids.list, e, 20, MINING_LASERS[3].range)) ?? null;
  const w51resistRock = ctxI.asteroids.list.find((e) => e.oreKey === 'chromeSalt'
    && w51ClearLine(ctxI.asteroids.list, e, 20, MINING_LASERS[3].range)) ?? null;
  let w51softUnits = 0;
  let w51resistUnits = 0;
  let w51softCommodityOk = false;
  let w51softTintOk = false;
  let w51resistCommodityOk = false;
  if (w51softRock) {
    w51AimAt(ctxI, w51softRock, 20);
    ctxI.input.fireHeld = true;
    w51step(ctxI, [astI, combatI], W51_FIRE_FRAMES, { id: w51softRock.id, gap: 20 });
    ctxI.input.fireHeld = false;
    w51softUnits = w51podUnits();
    w51softCommodityOk = ctxI.pods.length > 0
      && ctxI.pods.every((p) => p.contents.every((c) => c.commodity === 'rawOre'));
    w51softTintOk = ctxI.pods.length > 0
      && ctxI.pods.every((p) => p.mesh.material.color.getHex() === ORE_TYPES.rawOre.podTint);
  }
  ctxI.pods.length = 0; // clear between runs — the scoped scene dies with the pin
  if (w51resistRock) {
    w51AimAt(ctxI, w51resistRock, 20);
    ctxI.input.fireHeld = true;
    w51step(ctxI, [astI, combatI], W51_FIRE_FRAMES, { id: w51resistRock.id, gap: 20 });
    ctxI.input.fireHeld = false;
    w51resistUnits = w51podUnits();
    w51resistCommodityOk = ctxI.pods.length > 0
      && ctxI.pods.every((p) => p.contents.every((c) => c.commodity === 'chromeSalt'));
  }
  const w51iChecks = {
    softRockFound: !!w51softRock,
    resistRockFound: !!w51resistRock,
    softPodsCarryRawOre: w51softCommodityOk,
    softPodsTinted: w51softTintOk,
    softRunProductive: w51softUnits >= 7, // theory: 4.4 u/s × ~2 s ≈ 8 units
    resistRunProductive: w51resistUnits >= 1,
    resistStrictlySlower: w51resistUnits < w51softUnits, // theory: 4.4/1.9 × ~2 s ≈ 4 units
    resistPodsCarryChromeSalt: w51resistCommodityOk,
  };
  console.log('wave51i extraction resist + pod tint:', JSON.stringify(w51iChecks),
    `rawOre=${w51softUnits}u chromeSalt=${w51resistUnits}u frames=${W51_FIRE_FRAMES}`);
  if (!Object.values(w51iChecks).every(Boolean)) { console.log('WAVE51I EXTRACTION RESIST FAIL'); errors++; }

  // -- j. the outfitter ladder through the REAL station UI ----------------
  // Dock at freehold, open outfitting, and drive the real buttons/digits:
  // one live button at the stock head naming the Mk II and its 1400 UU
  // price; the poor click refused; the real buy deducting EXACTLY 1400;
  // the Mk IV hotkey from rung 1 refused (no rung skipping); the ladder
  // walked to 3, after which three installed notes stand and NO live
  // mining button remains. Buttons are re-found after EVERY action —
  // render() rebuilds the overlay DOM (the wave-30/31 discipline).
  ctx.world.miningLaser = 0; // TEST SETUP: ladder start (k re-pins every rung below)
  w30parkHostiles('wave51 hostiles parked (outfitter dock)');
  dockAtCurrentStation('wave51 dock freehold (outfitter)');
  dispatchKey('Digit6'); // outfitting (DOCK_KEY_SERVICES[5])
  const w51outfitOpen = [...walkDom(stationOverlay() ?? { children: [] })]
    .some((n) => n.textContent === 'OUTFITTING — hull work & instruments');
  const w51miningBtns = () => {
    const ov = stationOverlay();
    if (!ov) return [];
    return [...walkDom(ov)].filter((n) => n.tagName === 'BUTTON'
      && /^\d — (Bore laser Mk II|Ferrous cutting head Mk III|Deepcore lance Mk IV) \(\d+ UU\)$/.test(n.textContent ?? ''));
  };
  const w51installedNotes = () => [...walkDom(stationOverlay() ?? { children: [] })]
    .filter((n) => typeof n.textContent === 'string'
      && /^(Bore laser Mk II|Ferrous cutting head Mk III|Deepcore lance Mk IV) fitted — cuts hardness /.test(n.textContent));
  const w51btnsAtStock = w51miningBtns();
  ctx.world.credits = 500; // TEST SETUP: below the Mk II price
  w51miningBtns()[0]?.click(); // the poor click — refused through the real handler
  const w51poorRefused = ctx.world.miningLaser === 0;
  ctx.world.credits = 20000;
  w51miningBtns()[0]?.click(); // the real Mk II buy
  const w51mk2Bought = ctx.world.miningLaser === 1 && ctx.world.credits === 20000 - 1400;
  dispatchKey('Digit7'); // the Mk IV rung from rung 1 — the prerequisite guard
  const w51noSkip = ctx.world.miningLaser === 1 && ctx.world.credits === 20000 - 1400;
  const w51btnMk3 = w51miningBtns().find((b) => b.textContent === '6 — Ferrous cutting head Mk III (4200 UU)') ?? null;
  w51btnMk3?.click();
  const w51mk3Bought = ctx.world.miningLaser === 2 && ctx.world.credits === 20000 - 1400 - 4200;
  const w51btnMk4 = w51miningBtns().find((b) => b.textContent === '7 — Deepcore lance Mk IV (11000 UU)') ?? null;
  w51btnMk4?.click();
  const w51mk4Bought = ctx.world.miningLaser === 3 && ctx.world.credits === 20000 - 1400 - 4200 - 11000;
  const w51jChecks = {
    outfittingOpen: w51outfitOpen,
    oneLiveButtonAtStock: w51btnsAtStock.length === 1
      && w51btnsAtStock[0]?.textContent === '5 — Bore laser Mk II (1400 UU)',
    poorClickRefused: w51poorRefused,
    mk2BuyExact1400: w51mk2Bought,
    noRungSkipping: w51noSkip,
    mk3BuyExact4200: w51mk3Bought,
    mk4BuyExact11000: w51mk4Bought,
    threeInstalledNoLiveButton: w51installedNotes().length === 3 && w51miningBtns().length === 0,
  };
  console.log('wave51j outfitter ladder:', JSON.stringify(w51jChecks), `credits=${ctx.world.credits}`);
  if (!Object.values(w51jChecks).every(Boolean)) { console.log('WAVE51J OUTFITTER LADDER FAIL'); errors++; }
  undockStation(); // leave the dock as the wave-40 discipline found it

  // -- k. save roundtrip: the rung rides the dock autosave, tampering heals
  // The wave-34 scanner-heal idiom, verbatim: poke ctx.world.miningLaser,
  // dock (the 'docked' event fires trySave), poll the store for the save
  // carrying BOTH the poke and a per-case sentinel credits value (rung
  // values repeat across this run's autosaves — the sentinel proves the
  // matched save is THIS dock's), die, recover via Enter. Legit 2
  // survives; 99, '2', null, and 2.5 heal to EXACTLY 0 (a hand-edited
  // miningLaser must not restore with Deepcore reach for free).
  const w51saveCases = [
    { poke: 2, expect: 2 }, // a legit rung rides the roundtrip unchanged
    { poke: 99, expect: 0 }, // tampered: off the ladder
    { poke: '2', expect: 0 }, // tampered: right rung, wrong type
    { poke: null, expect: 0 }, // tampered: JSON null
    { poke: 2.5, expect: 0 }, // tampered: fractional rung
  ];
  const w51saveResults = [];
  for (let ci = 0; ci < w51saveCases.length; ci++) {
    const { poke: w51poke, expect: w51expect } = w51saveCases[ci];
    const w51sentinel = 71231 + ci * 7; // unique per case, provably unlike any earlier autosave
    if (ctx.flags.docked) undockStation(); // a death-restore ends docked (the wave-34 note)
    ctx.world.miningLaser = w51poke; // TEST SETUP tamper (the wave-34 scanner poke pattern)
    ctx.world.credits = w51sentinel; // TEST SETUP sentinel (the wave-30 credits-drift idiom)
    w30parkHostiles('wave51 hostiles parked (miningLaser save)');
    dockAtCurrentStation('wave51 dock freehold (miningLaser heal)'); // 'docked' fires trySave
    let w51snap = null;
    for (let i = 0; i < 60 * 15 && !w51snap; i++) { // the wave-30 save-wait discipline
      for (const s of ctx.ships) if (w30isHostile(s) && s.object) s.object.position.set(9000, 9000, 9000);
      tick(1, 'wave51 miningLaser save wait');
      try {
        const s = JSON.parse(store.get('rimward-save-v1') ?? 'null');
        if (s?.world && 'miningLaser' in s.world && s.world.miningLaser === w51poke
          && s.world.credits === w51sentinel) w51snap = s;
      } catch { /* keep waiting */ }
    }
    // Die + recover (the wave-26 restore path): a tampered rung loses to the sanitizer.
    ctx.emit('playerDestroyed', {});
    tick(2, 'wave51 death consumed (miningLaser heal)');
    dispatchKey('Enter'); // recover(): restore(last save)
    tick(2, 'wave51 miningLaser restore settle');
    w51saveResults.push({
      poke: String(w51poke),
      saveCarriesPoke: w51snap !== null, // the poll's predicate already gates value + sentinel
      miningLaserHealed: ctx.world.miningLaser === w51expect,
      restoreReadOurSave: ctx.world.credits === w51sentinel,
    });
  }
  const w51kOk = w51saveResults.every((r) => r.saveCarriesPoke && r.miningLaserHealed && r.restoreReadOurSave);
  console.log('wave51k miningLaser restore heal:', JSON.stringify(w51saveResults));
  if (!w51kOk) { console.log('WAVE51K MININGLASER HEAL FAIL'); errors++; }
  if (ctx.flags.docked) undockStation();

  // -- l. economy negatives: manifests stay staple, events move the ores --
  // LEGAL_KEYS-equivalent recomputation straight off COMMODITIES (the pin
  // IS the independent recomputation): NPC trader manifests must remain
  // byte-identical to pre-wave-51 — legal && bulk excludes every exotic.
  // Then the real applyEventPressure + tickPrices path on a scoped verge
  // context (module pressure keyed off the live freehold market is never
  // touched): strikeRush floods the h2 ores a basic head can cut but never
  // the h4 pair; oreRush crashes the h2/h3 ores and LIFTS voidPlatinum and
  // wakeglass. Math.random pinned to 0.5 zeroes the random walk so the
  // pull is deterministic (the wave-34 pin discipline); the loop shape is
  // settlePrices' own (300 × 0.5 s). Pressure is cleared after — hygiene.
  const ctxE = w51scopedCtx('verge');
  initPrices(ctxE);
  const w51basePrices = { ...ctxE.world.prices };
  const w51origRandom = Math.random;
  Math.random = () => 0.5;
  let w51strikePrices = null;
  let w51rushPrices = null;
  try {
    applyEventPressure(ctxE, 'strikeRush');
    for (let i = 0; i < 300; i++) tickPrices(ctxE, 0.5);
    w51strikePrices = { ...ctxE.world.prices };
    applyEventPressure(ctxE, 'clear', 'verge');
    applyEventPressure(ctxE, 'oreRush');
    for (let i = 0; i < 300; i++) tickPrices(ctxE, 0.5);
    w51rushPrices = { ...ctxE.world.prices };
    applyEventPressure(ctxE, 'clear', 'verge');
  } finally {
    Math.random = w51origRandom;
  }
  const w51legalKeys = Object.keys(COMMODITIES).filter((k) => COMMODITIES[k].legal && COMMODITIES[k].bulk);
  const w51lChecks = {
    legalKeysExact: JSON.stringify(w51legalKeys) === JSON.stringify(['provisions', 'refinedMetals', 'rawOre', 'livingRock']),
    strikeCrashesH2: w51strikePrices.slagIron < w51basePrices.slagIron
      && w51strikePrices.brineIce < w51basePrices.brineIce,
    strikeLeavesH4Alone: w51strikePrices.voidPlatinum === w51basePrices.voidPlatinum
      && w51strikePrices.wakeglass === w51basePrices.wakeglass,
    rushCrashesH2H3: w51rushPrices.slagIron < w51basePrices.slagIron
      && w51rushPrices.brineIce < w51basePrices.brineIce
      && w51rushPrices.chromeSalt < w51basePrices.chromeSalt
      && w51rushPrices.emberglass < w51basePrices.emberglass
      && w51rushPrices.gildvein < w51basePrices.gildvein,
    rushLiftsH4: w51rushPrices.voidPlatinum > w51basePrices.voidPlatinum
      && w51rushPrices.wakeglass > w51basePrices.wakeglass,
  };
  console.log('wave51l economy negatives:', JSON.stringify(w51lChecks),
    `slagIron=${w51basePrices.slagIron}→${w51strikePrices.slagIron}/${w51rushPrices.slagIron} voidPlatinum=${w51basePrices.voidPlatinum}→${w51strikePrices.voidPlatinum}/${w51rushPrices.voidPlatinum}`);
  if (!Object.values(w51lChecks).every(Boolean)) { console.log('WAVE51L ECONOMY NEGATIVES FAIL'); errors++; }

  // -- m. authored price spread: the haul-coreward loop is real -----------
  // Recomputed from SYSTEMS + COMMODITIES, independent of market.js: every
  // authored system carries all seven exotic ore priceBases; the 94
  // generated systems carry NONE (they fall through to ×1.0 in
  // baselineFor); and the deep rim prices wakeglass below the core. The
  // strict pins are verge-below-BOTH band-0 systems and hush-below-
  // freehold — hush TIES veridian at 0.85, so a blanket deep<core
  // strictness would be a false pin; the loop the data guarantees is
  // verge → core (0.70 vs 1.40/0.85).
  const W51_NEW_ORES = ['slagIron', 'brineIce', 'chromeSalt', 'gildvein', 'emberglass', 'voidPlatinum', 'wakeglass'];
  const w51authoredIds = Object.keys(AUTHORED_SYSTEMS);
  const w51generatedIds = Object.keys(SYSTEMS).filter((id) => !AUTHORED_SYSTEMS[id]);
  const w51wgEff = (id) => COMMODITIES.wakeglass.base * SYSTEMS[id].priceBase.wakeglass;
  const w51mChecks = {
    authoredCarryAllSeven: w51authoredIds.every((id) => W51_NEW_ORES
      .every((k) => Number.isFinite(SYSTEMS[id].priceBase?.[k]))),
    generatedCarryNone: w51generatedIds.length > 0 && w51generatedIds.every((id) => W51_NEW_ORES
      .every((k) => !(k in (SYSTEMS[id].priceBase ?? {})))),
    vergeBelowEveryCore: w51wgEff('verge') < w51wgEff('freehold') && w51wgEff('verge') < w51wgEff('veridian'),
    hushBelowFreehold: w51wgEff('hush') < w51wgEff('freehold'),
  };
  console.log('wave51m authored price spread:', JSON.stringify(w51mChecks),
    `wakeglassEff=${w51authoredIds.map((id) => `${id}:${w51wgEff(id)}`).join(',')}`);
  if (!Object.values(w51mChecks).every(Boolean)) { console.log('WAVE51M AUTHORED SPREAD FAIL'); errors++; }

  // -- n. models catalog: one prop per ore plus the cargo pod -------------
  // The Props tab is how the nine ores get reviewed: exactly one entry per
  // ORE_KEYS member plus the pre-existing cargo pod; every ore prop builds
  // a real { object, update, label } model naming its ore; and two builds
  // of the same prop yield identical geometry vertex counts — the seed is
  // derived from the ore's index, never a random draw.
  const w51props = MODEL_CATALOG.filter((e) => e.category === 'Props');
  const w51oreProps = ORE_KEYS.map((k) => w51props.filter((p) => p.id === `prop:asteroid:${k}`));
  let w51buildShape = true;
  let w51vertsDeterministic = true;
  for (let i = 0; i < ORE_KEYS.length; i++) {
    const entry = w51oreProps[i][0];
    if (!entry || typeof entry.build !== 'function') { w51buildShape = false; continue; }
    const m1 = entry.build();
    const m2 = entry.build();
    if (!m1?.object || typeof m1.update !== 'function'
      || m1.label !== `${COMMODITIES[ORE_KEYS[i]].name} asteroid`) w51buildShape = false;
    const v1 = m1?.object?.geometry?.attributes?.position?.count ?? -1;
    const v2 = m2?.object?.geometry?.attributes?.position?.count ?? -2;
    if (v1 < 0 || v1 !== v2) w51vertsDeterministic = false;
  }
  const w51nChecks = {
    propsCountIsOresPlusPod: w51props.length === ORE_KEYS.length + 1,
    onePropPerOre: w51oreProps.every((list) => list.length === 1),
    cargoPodPresent: w51props.some((p) => p.id === 'prop:pod'),
    buildShapeAndLabel: w51buildShape,
    vertexCountDeterministic: w51vertsDeterministic,
  };
  console.log('wave51n models catalog props:', JSON.stringify(w51nChecks), `props=${w51props.length}`);
  if (!Object.values(w51nChecks).every(Boolean)) { console.log('WAVE51N MODELS CATALOG FAIL'); errors++; }

  const wLmCat = MODEL_CATALOG.filter((e) => e.category === 'Landmarks');
  const wLmAuthoredIds = [
    'fh_shepherd', 'vd_hulk_row', 'rm_tithe_stone', 'hr_quiet_beacon',
    'hr_first_wreck', 'th_lanes_end', 'th_first_garden', 'th_veil',
    'vg_choir_stones', 'vg_unfinished', 'convergence', 'deepening',
  ];
  const wLmCountVerts = (obj) => {
    let n = 0;
    obj.traverse((o) => { n += o.geometry?.attributes?.position?.count ?? 0; });
    return n;
  };
  let wLmAuthoredTagged = true;
  for (const id of wLmAuthoredIds) {
    const entry = wLmCat.find((e) => e.id === `landmark:authored:${id}`);
    if (!entry) { wLmAuthoredTagged = false; continue; }
    if (id === 'th_veil') continue; // hush catalogs th_veil; AUTHORED has no unique hero
    const built = entry.build();
    if (built?.object?.userData?.authored !== id) wLmAuthoredTagged = false;
  }
  const wLmWreckA = wLmCat.find((e) => e.id === 'landmark:wreck:independent')?.build();
  const wLmWreckB = wLmCat.find((e) => e.id === 'landmark:wreck:independent')?.build();
  const wLmVa = wLmWreckA?.object ? wLmCountVerts(wLmWreckA.object) : -1;
  const wLmVb = wLmWreckB?.object ? wLmCountVerts(wLmWreckB.object) : -2;
  const wLmChecks = {
    catalogCount22: wLmCat.length === 22,
    authoredNamed: wLmAuthoredIds.every((id) => wLmCat.some((e) => e.id === `landmark:authored:${id}`)),
    authoredDispatch: wLmAuthoredTagged,
    kindDeterministic: wLmVa > 10 && wLmVa === wLmVb,
  };
  console.log('landmark redesign catalog:', JSON.stringify(wLmChecks), `verts=${wLmVa}`);
  if (!Object.values(wLmChecks).every(Boolean)) { console.log('LANDMARK REDESIGN CATALOG FAIL'); errors++; }
}

// Unknowable fields: projectiles do not couple; the mining beam does.
// Isolated applyHit contract — no combat scene, no full-boot tick.
{
  const { applyHit, createShipState } = await import('../src/game/state.js');
  const snap = (s) => ({
    hull: s.hull, screen: s.screen, shell: s.shell, engine: s.engine,
    lastHitAt: s.lastHitAt, lastCombatAt: s.lastCombatAt,
  });
  const frozen = (a, b) => a.hull === b.hull && a.screen === b.screen
    && a.shell === b.shell && a.engine === b.engine
    && a.lastHitAt === b.lastHitAt && a.lastCombatAt === b.lastCombatAt;

  const unkCannon = createShipState('light', { faction: 'unknowables' });
  const beforeCannon = snap(unkCannon);
  const evCannon = applyHit(unkCannon, { damage: 20, family: 'cannon', now: 10 });
  const evEnergy = applyHit(unkCannon, { damage: 20, family: 'energy', now: 10 });

  const unkDisc = createShipState('light', { faction: 'unknowables' });
  const beforeDisc = snap(unkDisc);
  const evDisc = applyHit(unkDisc, { damage: 20, family: 'disruptor', now: 10 });

  const unkMine = createShipState('light', { faction: 'unknowables' });
  const beforeMine = snap(unkMine);
  const evMine = applyHit(unkMine, { damage: 20, family: 'mining', now: 10 });

  const indy = createShipState('light', { faction: 'independent' });
  const beforeIndy = snap(indy);
  const evIndy = applyHit(indy, { damage: 20, family: 'cannon', now: 10 });

  const unkWeaponChecks = {
    cannonNoOp: evCannon.length === 0 && frozen(snap(unkCannon), beforeCannon),
    energyNoOp: evEnergy.length === 0 && frozen(snap(unkCannon), beforeCannon),
    disruptorNoOp: evDisc.length === 0 && frozen(snap(unkDisc), beforeDisc),
    miningHurts: (unkMine.hull < beforeMine.hull || unkMine.screen < beforeMine.screen
      || unkMine.shell < beforeMine.shell) && evMine != null,
    independentHurts: (indy.hull < beforeIndy.hull || indy.screen < beforeIndy.screen
      || indy.shell < beforeIndy.shell) && evIndy.length >= 0,
  };
  console.log('unknowable weapon coupling:', JSON.stringify(unkWeaponChecks));
  if (!Object.values(unkWeaponChecks).every(Boolean)) {
    console.log('UNKNOWABLE WEAPON COUPLING FAIL');
    errors++;
  }
}

// G0 gate kit: scale contracts, seeded tunnel, hub lantern extra.
// Isolated — no travel. Overlay-on-torus census pins are retired (R10 / G13).
{
  const { JUMP: jG0 } = await import('../src/game/state.js');
  const gs = await import('../src/game/gate-scale.js');
  const gd = await import('../src/systems/gate-detail.js');
  const { buildGateModel } = await import('../src/systems/gate.js');
  const tA = new Float32Array(gs.TUNNEL_COUNT * 2);
  const tZ = new Float32Array(gs.TUNNEL_COUNT);
  const tA2 = new Float32Array(gs.TUNNEL_COUNT * 2);
  const tZ2 = new Float32Array(gs.TUNNEL_COUNT);
  const seed = gd.seedFromParts('g0', 'kit');
  gd.fillTunnelArrays(tA, tZ, seed);
  gd.fillTunnelArrays(tA2, tZ2, seed);
  let tunSame = true;
  for (let i = 0; i < tA.length; i++) if (tA[i] !== tA2[i]) tunSame = false;
  const m1 = buildGateModel('independent');
  const hub = buildGateModel('lamplighter', { hub: true, routes: 3 });
  const g0Checks = {
    zone: gs.ZONE === jG0.zone,
    arrival: gs.ARRIVAL_OFFSET === jG0.arrivalOffset,
    bore: gs.BORE_RADIUS === 30 && gs.OUTLINE_BREAKER_MIN === 9,
    tunnelDeterministic: tunSame,
    catalogBuilds: !!m1.object,
    hubLantern: hub.object.userData.routeCount === 3,
    censusHead: gs.GATE_REBUILD_ORDER[0] === 'freehold',
  };
  console.log('g0 gate kit:', JSON.stringify(g0Checks));
  if (!Object.values(g0Checks).every(Boolean)) { console.log('G0 GATE KIT FAIL'); errors++; }
}

// G13 closeout: leftover RING torus / overlay chassis is gone. Catalog
// models are faction sculpts named '<faction>-gate' with no '*-overlay' child.
{
  const { GATE_REBUILD_ORDER } = await import('../src/game/gate-scale.js');
  const { buildGateModel } = await import('../src/systems/gate.js');
  const g13 = {
    allNamed: true,
    noOverlayChild: true,
    hasHullMesh: true,
    independentSculpt: false,
    hollowSculpt: false,
    hubLantern: false,
  };
  for (const f of GATE_REBUILD_ORDER) {
    const { object } = buildGateModel(f);
    if (object.name !== `${f}-gate`) g13.allNamed = false;
    if (object.children.some((c) => c.name?.endsWith('-overlay'))) g13.noOverlayChild = false;
    let verts = 0;
    object.traverse((o) => { if (o.isMesh) verts += o.geometry?.attributes?.position?.count ?? 0; });
    if (verts <= 500) g13.hasHullMesh = false;
    if (f === 'independent') g13.independentSculpt = object.name === 'independent-gate' && verts > 500;
    if (f === 'hollow') g13.hollowSculpt = object.name === 'hollow-gate' && verts > 500;
  }
  const hub = buildGateModel('lamplighter', { hub: true, routes: 3 });
  g13.hubLantern = hub.object.userData.routeCount === 3;
  console.log('g13 closeout:', JSON.stringify(g13));
  if (!Object.values(g13).every(Boolean)) { console.log('G13 CLOSEOUT FAIL'); errors++; }
}

// ---- HUD-01: mirrored central combat status (player + target rails) --------
// New glance clusters live under the memoized #hud root. Visibility of the
// target rail is a classList is-hidden flip (same stub contract as wave 15).
// Existing wave-15 chartmark and wave-31 bracket class names must still
// resolve once under that root.
{
  const hud01has = (n, cls) => typeof n.className === 'string' && n.className.split(' ').includes(cls);
  const hud01nodes = (cls) => [...walkDom(document.getElementById('hud'))]
    .filter((n) => hud01has(n, cls));
  const hud01shown = (n) => n && !n.classList.contains('is-hidden');

  const prevTgt01 = ctx.targets.current;
  ctx.targets.current = null;
  tick(3, 'hud01 no target');
  const selfRails = hud01nodes('rw-combat-self');
  const tgtRails = hud01nodes('rw-combat-target');
  const hiddenNone = tgtRails.length > 0 && tgtRails.every((n) => !hud01shown(n));

  const rec01 = {
    id: 'hud01-mark', name: 'HUD01 MARK', classKey: 'freighter',
    faction: 'independent', role: 'trader', resolve: 50,
  };
  const origin01 = ctx.ship.object ? ctx.ship.object.position.clone() : new THREE.Vector3();
  let live01 = spawnLiveShip(ctx, rec01, origin01.clone().add(new THREE.Vector3(80, 0, 0)));
  let spawned01 = false;
  if (live01) {
    ctx.ships.push(live01);
    spawned01 = true;
  } else {
    live01 = (ctx.ships ?? []).find((s) => s?.state && !s.state.destroyed && s.object) ?? null;
  }
  if (live01?.state) {
    live01.state.screen = 12;
    live01.state.screenMax = 24;
    live01.state.shell = 40;
    live01.state.shellMax = 80;
    live01.state.hull = 50;
    live01.state.hullMax = 100;
    live01.state.name = 'HUD01 MARK';
    if (live01.record) {
      live01.record.name = 'HUD01 MARK';
      if (live01.record.qship && !live01.record.revealed) live01.record.coverName = 'HUD01 MARK';
    }
  }
  ctx.targets.current = live01;
  tick(15, 'hud01 live ship target');
  const shownRails = tgtRails.filter(hud01shown);
  const rail01 = shownRails[0] ?? null;
  const railKids = rail01 ? [...walkDom(rail01)] : [];
  const nameShown = railKids.some((n) => hud01has(n, 'rw-combat-name')
    && typeof n.textContent === 'string' && n.textContent.includes('HUD01 MARK'));
  const distShown = railKids.some((n) => hud01has(n, 'rw-combat-dist')
    && typeof n.textContent === 'string' && /\d/.test(n.textContent));

  ctx.targets.current = live01
    ? { object: live01.object, state: { ...live01.state, destroyed: true }, record: live01.record }
    : { state: { destroyed: true, name: 'HUD01 MARK' } };
  tick(3, 'hud01 destroyed target');
  const hiddenWhenDestroyed = tgtRails.every((n) => !hud01shown(n));

  ctx.targets.current = {
    position: origin01.clone(),
    ore: 8,
    commodity: 'rawOre',
    hardness: 1,
  };
  tick(3, 'hud01 asteroid target');
  const hiddenAsteroid = tgtRails.every((n) => !hud01shown(n));

  ctx.targets.current = prevTgt01;
  if (spawned01 && live01) {
    const i01 = ctx.ships.indexOf(live01);
    if (i01 >= 0) ctx.ships.splice(i01, 1);
    removeLiveShip(ctx, live01);
  }

  const hud01 = {
    selfPresent: selfRails.length > 0,
    targetPresent: tgtRails.length > 0,
    hiddenWithoutTarget: hiddenNone,
    shownOnLiveShip: shownRails.length > 0,
    nameShown,
    distShown,
    hiddenWhenDestroyed,
    hiddenOnAsteroid: hiddenAsteroid,
    chartmarkSelector: hud01nodes('rw-chartmark').length > 0
      && hud01nodes('rw-chartmark-label').length > 0,
    targetBracketSelector: hud01nodes('rw-target').length > 0
      && hud01nodes('rw-target-name').length > 0
      && hud01nodes('rw-target-meta').length > 0,
  };
  console.log('hud01 mirrored combat rails:', JSON.stringify(hud01));
  if (!Object.values(hud01).every(Boolean)) { console.log('HUD01 COMBAT RAILS FAIL'); errors++; }
}

// ---- HUD utility waves B–E (hail slot, facing, lead/MATCH, first-person) ----
{
  const hailCard = [...walkDom(document.body)].find((n) => n.className === 'rw-hail-card');
  const hailCss = hailCard?.style?.cssText || '';
  const hintEl = [...walkDom(document.body)].find((n) => n.className === 'rw-onboard-hint');
  const hintCss = hintEl?.style?.cssText || '';
  const waveB = {
    hailCard: !!hailCard,
    hailLowerLeft: hailCss.includes('left:14px') && hailCss.includes('bottom:22%'),
    hailMax360: hailCss.includes('360px'),
    hintOffBottom: hintCss.includes('top:48px') && hintCss.includes('left:14px')
      && !hintCss.includes('bottom:6%'),
  };
  console.log('hud wave B hail/onboard:', JSON.stringify(waveB));
  if (!Object.values(waveB).every(Boolean)) { console.log('HUD WAVE B FAIL'); errors++; }

  const facingHas = (cls) => [...walkDom(document.getElementById('hud'))]
    .some((n) => typeof n.className === 'string' && n.className.split(' ').includes(cls));
  const facingFlash = (cls) => [...walkDom(document.getElementById('hud'))]
    .some((n) => typeof n.className === 'string' && n.className.split(' ').includes(cls)
      && n.classList.contains('is-flash'));
  const waveCpre = {
    facingPresent: facingHas('rw-facing') && facingHas('rw-facing-fore') && facingHas('rw-facing-aft'),
  };
  ctx.emit('playerHit', { damage: 1, family: 'cannon', fromAft: true, shielded: true });
  tick(1, 'hud wave C aft flash');
  const waveC = {
    ...waveCpre,
    aftFlash: facingFlash('rw-facing-aft'),
    foreQuiet: !facingFlash('rw-facing-fore'),
  };
  console.log('hud wave C facing:', JSON.stringify(waveC));
  if (!Object.values(waveC).every(Boolean)) { console.log('HUD WAVE C FAIL'); errors++; }

  ctx.flags.docked = false;
  ctx.gate.jumping = false;
  const prevTgtD = ctx.targets.current;
  const recD = {
    id: 'hud-d-mark', name: 'HUD D MARK', classKey: 'light',
    faction: 'independent', role: 'trader', resolve: 40,
  };
  const originD = ctx.ship.object ? ctx.ship.object.position.clone() : new THREE.Vector3();
  let liveD = spawnLiveShip(ctx, recD, originD.clone().add(new THREE.Vector3(40, 0, -20)));
  let spawnedD = false;
  if (liveD) { ctx.ships.push(liveD); spawnedD = true; }
  else liveD = (ctx.ships ?? []).find((s) => s?.state && !s.state.destroyed && s.object) ?? null;
  ctx.targets.current = liveD;
  ctx.input.weaponGroup = 2;
  const throttleBefore = ctx.input.throttle;
  dispatchKey('KeyX');
  tick(2, 'hud wave D match + disruptor');
  const matchOn = ctx.flags.matchSpeed === true;
  const throttleUntouched = ctx.input.throttle === throttleBefore;
  ctx.input.weaponGroup = 3;
  tick(2, 'hud wave D mining hides pip');
  const leadHidden = [...walkDom(document.getElementById('hud'))]
    .filter((n) => typeof n.className === 'string' && n.className.split(' ').includes('rw-lead'))
    .every((n) => n.classList.contains('is-hidden'));
  dispatchKey('KeyX');
  tick(1, 'hud wave D match off');
  const matchOff = ctx.flags.matchSpeed === false;
  ctx.targets.current = prevTgtD;
  if (spawnedD && liveD) {
    const iD = ctx.ships.indexOf(liveD);
    if (iD >= 0) ctx.ships.splice(iD, 1);
    removeLiveShip(ctx, liveD);
  }
  const waveD = { matchOn, throttleUntouched, leadHidden, matchOff };
  console.log('hud wave D aim/match:', JSON.stringify(waveD));
  if (!Object.values(waveD).every(Boolean)) { console.log('HUD WAVE D FAIL'); errors++; }

  const prevCam = ctx.flags.camera;
  ctx.flags.camera = 'first';
  ctx.flags.firstPerson = true;
  tick(2, 'hud wave E first-person');
  const camZ = FIRST_PERSON_NOSE.z;
  const pastTip = camZ <= -2.5;
  const noseMoved = FIRST_PERSON_NOSE.y === 0.45 && camZ === -2.8;
  ctx.flags.camera = prevCam || 'chase';
  ctx.flags.firstPerson = ctx.flags.camera === 'first';
  tick(1, 'hud wave E restore cam');
  const waveE = { pastTip, noseMoved };
  console.log('hud wave E first-person:', JSON.stringify(waveE));
  if (!Object.values(waveE).every(Boolean)) { console.log('HUD WAVE E FAIL'); errors++; }
}

// ---- HUD Wave F: scanner-gated bottom bearing arc (not a reticle ring) ----
{
  const hudFhas = (n, cls) => !!(n.classList && n.classList.contains(cls));
  const hudFnodes = (cls) => [...walkDom(document.getElementById('hud'))]
    .filter((n) => hudFhas(n, cls));
  const hudFshown = (n) => n && !n.classList.contains('is-hidden');
  const prevScanF = ctx.world.scanner;
  const prevDockF = ctx.flags.docked;
  const prevTgtF = ctx.targets.current;
  const prevPosF = ctx.ship.object ? ctx.ship.object.position.clone() : null;
  ctx.flags.docked = false;
  ctx.world.scanner = 0;
  if (ctx.ship.object) ctx.ship.object.position.set(2400, 40, 2400);
  tick(2, 'hud wave F scanner 0');
  const arcs = hudFnodes('rw-contacts').filter((n) => n.tagName === 'DIV');
  const hiddenCore = arcs.length > 0 && arcs.every((n) => !hudFshown(n));

  ctx.world.scanner = 1;
  tick(2, 'hud wave F scanner 1 empty');
  const shownMk1 = arcs.some(hudFshown);

  const recF = {
    id: 'hud-f-mark', name: 'HUD F MARK', classKey: 'light',
    faction: 'independent', role: 'pirate', resolve: 40,
  };
  const originF = ctx.ship.object ? ctx.ship.object.position.clone() : new THREE.Vector3();
  let liveF = spawnLiveShip(ctx, recF, originF.clone().add(new THREE.Vector3(0, 0, 80)));
  let spawnedF = false;
  if (liveF) { ctx.ships.push(liveF); spawnedF = true; }
  else liveF = (ctx.ships ?? []).find((s) => s?.state && !s.state.destroyed && s.object) ?? null;
  if (liveF?.ai) {
    liveF.ai.mode = 'loiter';
    liveF.ai.target = null;
    liveF.ai.intent = false;
  }
  tick(3, 'hud wave F civilian aft');
  const civPip = hudFnodes('rw-contact-pip').some((n) => hudFshown(n) && hudFhas(n, 'is-civ'));

  if (liveF?.ai) {
    liveF.ai.mode = 'hunt';
    liveF.ai.target = 'player';
    liveF.ai.phase = 'telegraph';
    liveF.ai.intent = true;
    liveF.ai.playerRolled = true;
    liveF.ai.playerInterested = true;
  }
  tick(3, 'hud wave F hostile');
  const hostilePip = hudFnodes('rw-contact-pip').some((n) => hudFshown(n) && hudFhas(n, 'is-hostile'));

  ctx.targets.current = liveF;
  tick(3, 'hud wave F lock');
  const lockPip = hudFnodes('rw-contact-pip').some((n) => hudFshown(n) && hudFhas(n, 'is-lock'));

  ctx.flags.docked = true;
  tick(2, 'hud wave F docked');
  const hiddenDocked = arcs.every((n) => !hudFshown(n));

  ctx.flags.docked = false;
  ctx.world.scanner = 2;
  tick(3, 'hud wave F mk2');
  const shownMk2 = arcs.some(hudFshown);
  const lockStill = hudFnodes('rw-contact-pip').some((n) => hudFshown(n) && hudFhas(n, 'is-lock'));

  ctx.world.scanner = prevScanF;
  ctx.flags.docked = prevDockF;
  ctx.targets.current = prevTgtF;
  if (prevPosF && ctx.ship.object) ctx.ship.object.position.copy(prevPosF);
  if (spawnedF && liveF) {
    const iF = ctx.ships.indexOf(liveF);
    if (iF >= 0) ctx.ships.splice(iF, 1);
    removeLiveShip(ctx, liveF);
  }
  tick(1, 'hud wave F restore');

  const waveF = {
    arcPresent: arcs.length >= 1,
    hiddenCore,
    shownMk1,
    civPip,
    hostilePip,
    lockPip,
    hiddenDocked,
    shownMk2,
    lockStill,
    bottomNotRing: true,
  };
  console.log('hud wave F contacts:', JSON.stringify(waveF));
  if (!Object.values(waveF).every(Boolean)) { console.log('HUD WAVE F FAIL'); errors++; }
}

