  if (ctx.flags.docked) undockStation();
  ctx.world.hangar = hangarKeep92;
  ctx.world.credits = creditsKeep92;
  ctx.world.reputation = { ...(ctx.world.reputation ?? {}), ...repKeep92 };
  ctx.player.hullKind = kindKeep92;
