    alreadyOk,
    fullGiftOk,
    rankOk,
    pirateOk,
    missOk,
    npcOk,
    fullPirateOk,
    protoOk,
    graftDrop,
    ...srcPins,
    digit0Shipyard,
    giftDeskArm,
    giftDeskOk,
    giftEscNoWrite,
    giftDigit1Arm,
    reachedCradle,
